  function ensureImportedTmmProject(database) {
    const source = window.AUDITFLOW_TMM_ASSESSMENT;
    if (!source || database.standardProjects.some(project => project.importSource?.importId === source.importId || project.id === source.project?.id)) return;
    const project = buildImportedTmmProject(source);
    if (!project) return;
    database.standardProjects.unshift(project);
    database.activity ||= [];
    database.activity.unshift({ icon: "upload", title: "TMM 专业评估报告已导入", detail: `${source.importStats.assessedProcesses} 个过程 · ${source.importStats.ratedPractices} 条实践评分 · 项目实施进度 100%`, date: new Date().toISOString() });
  }

  /* external assessment rating guard start */
  function guardExternalAssessmentProject(project, source) {
    if (!project || !source) return project;
    const mapper = window.AUDITFLOW_EXTERNAL_ASSESSMENT_MAPPING;
    const sourcePractices = new Map((source.processes || []).flatMap(process =>
      (process.practices || []).map(item => [`${process.id}|${item.practiceId}`, item])
    ));
    const sourceProcessResults = JSON.parse(JSON.stringify(project.processResults || []));
    project.assessments = (project.assessments || []).map(assessment => {
      const sourcePractice = sourcePractices.get(`${assessment.process}|${assessment.sourceAssessment?.practiceId || assessment.code}`);
      const mapped = mapper?.attach
        ? mapper.attach(assessment, sourcePractice || assessment.sourceAssessment || {})
        : { ...assessment };
      return {
        ...mapped,
        rating: "NR",
        displayRating: "NR",
        aiCandidateRating: null,
        achievementPercent: 0,
        confidence: 0,
        scoreBreakdown: { definition: 0, implementation: 0, consistency: 0, governance: 0, closure: 0 },
        reviewed: false,
        reviewStatus: "pending-assessor-confirmation",
        approvalStatus: "unconfirmed",
        assessorApprovedBy: null,
        assessorApprovedAt: null
      };
    });
    project.importSource = {
      ...(project.importSource || {}),
      ratingAuthority: "external-unconfirmed",
      externalDecisionStatus: "unconfirmed-import",
      externalProcessResults: sourceProcessResults
    };
    project.processResults = [];
    project.achievedLevel = "—";
    return project;
  }
  /* external assessment rating guard end */

