  function externalAssessmentSourceFingerprint(assessment) {
    const source = assessment?.sourceAssessment || {};
    return JSON.stringify({
      importId: source.importId || "",
      sourceFile: source.sourceFile || "",
      sheet: source.sheet || "",
      cellRange: source.cellRange || "",
      practiceId: source.practiceId || "",
      originalScore: source.originalScore ?? null,
      originalRating: source.originalRating || "",
      evidence: source.evidence || "",
      weakness: source.weakness || "",
      auditExplanation: source.auditExplanation || "",
      risk: source.risk || "",
      assessorComment: source.assessorComment || "",
      actionItems: source.actionItems || "",
      actionPlanIssue: source.actionPlanIssue || null,
      closureEvidence: source.closureEvidence || []
    });
  }

  function mergeExternalAssessmentOverrides(next, previous) {
    if (!next || !previous) return next;
    const humanFields = [
      "rating", "displayRating", "achievementPercent", "reviewed", "reviewStatus", "approvalStatus",
      "assessorApprovedBy", "assessorApprovedAt", "reviewerNote", "reviewerNoteEn", "reviewedAt", "reviewedBy",
      "ratingSource", "reason", "reasonEn", "refs", "findings", "findingStatus", "findingStatusBy", "findingStatusAt",
      "primaryIndicator", "impactIndicators", "mappingRationale", "mappingRationaleEn", "impactScope", "impactScopeEn",
      "mappingClosureCriteria", "mappingClosureCriteriaEn", "mappingCalibrated", "mappingStatus", "reconfirmationRequired",
      "reconfirmationReason"
    ];
    humanFields.forEach(field => {
      if (Object.prototype.hasOwnProperty.call(previous, field)) next[field] = deepCopy(previous[field]);
    });

    const linkKey = link => `${String(link?.evidenceId || link?.evidenceCode || "").trim()}|${String(link?.locator || "").trim()}`;
    const previousLinks = new Map((previous.evidenceAnalysis || []).map(link => [linkKey(link), link]));
    const retainedLinks = new Set();
    next.evidenceAnalysis = (next.evidenceAnalysis || []).map(link => {
      const previousLink = previousLinks.get(linkKey(link));
      if (!previousLink) return link;
      retainedLinks.add(linkKey(link));
      const merged = { ...link };
      ["confirmed", "confirmedBy", "confirmedAt", "reviewed", "reviewedBy", "reviewedAt", "evidenceRole", "strength", "scopeStatus"].forEach(field => {
        if (Object.prototype.hasOwnProperty.call(previousLink, field)) merged[field] = deepCopy(previousLink[field]);
      });
      return merged;
    });
    (previous.evidenceAnalysis || []).forEach(link => {
      const key = linkKey(link);
      if (retainedLinks.has(key) || !(link.confirmed || link.reviewed)) return;
      next.evidenceAnalysis.push(deepCopy(link));
    });

    const sourceChanged = externalAssessmentSourceFingerprint(previous) !== externalAssessmentSourceFingerprint(next);
    const hadHumanDecision = previous.reviewed === true || previous.ratingSource === "manual" || previous.mappingCalibrated === true || previous.approvalStatus === "confirmed";
    if (sourceChanged && hadHumanDecision) {
      next.reviewed = false;
      next.reviewStatus = "source-changed-pending-reconfirmation";
      next.approvalStatus = "reconfirmation-required";
      next.reconfirmationRequired = true;
      next.reconfirmationReason = "Imported source data changed after the last assessor decision; reconfirm the rating and evidence chain.";
      next.ratingSource = "manual-stale";
    }
    next.sourceAssessmentRevision = externalAssessmentSourceFingerprint(next);
    return next;
  }

  function mergeExternalRecordOverrides(next, previous) {
    if (!next || !previous) return next;
    ["attachments", "discussion", "status", "closureState", "closureChain", "owner", "ownerId", "dueDate", "assignee", "reviewedBy", "reviewedAt", "closureApproval", "ncFollowup"].forEach(field => {
      if (Object.prototype.hasOwnProperty.call(previous, field)) next[field] = deepCopy(previous[field]);
    });
    return next;
  }

  function refreshExternalAssessmentProject(existing, source) {
    const refreshed=buildImportedAssessmentProjectRaw(source);if(!refreshed)return existing;
    guardExternalAssessmentProject(refreshed, source);
    const prefix=source.project.id.replace(/[^A-Z0-9]/gi,"-");
    const generatedRecordPrefixes=[`${prefix}-W-`,`${prefix}-C-`];
    const existingRecords=new Map((existing.records||[]).map(record=>[record.id,record]));
    refreshed.records.forEach(record=>mergeExternalRecordOverrides(record,existingRecords.get(record.id)));
    const existingAssessments=new Map((existing.assessments||[]).map(assessment=>[assessment.id||`${assessment.process}|${assessment.code}`,assessment]));
    refreshed.assessments.forEach(assessment=>{
      const key=assessment.id||`${assessment.process}|${assessment.code}`;
      const previous=existingAssessments.get(key)||existingAssessments.get(`${assessment.process}|${assessment.code}`);
      mergeExternalAssessmentOverrides(assessment,previous);
    });
    const userRecords=(existing.records||[]).filter(record=>!generatedRecordPrefixes.some(recordPrefix=>record.id.startsWith(recordPrefix)));
    const preserved={
      records:[...refreshed.records,...userRecords],
      logs:[...(existing.logs||[]),...refreshed.logs],
      notepads:existing.notepads||[],sessions:existing.sessions||[],planCards:existing.planCards||[],
      runs:existing.runs?.length?existing.runs:refreshed.runs,
      reviewComments:existing.reviewComments||[],
      collaboration:existing.collaboration||refreshed.collaboration,
      participants:existing.participants?.length?existing.participants:refreshed.participants,
      workspaces:existing.workspaces?.length?existing.workspaces:refreshed.workspaces,
      instances:existing.instances?.length?existing.instances:refreshed.instances,
      activeWorkspaceId:existing.activeWorkspaceId||refreshed.activeWorkspaceId,
      activeInstanceId:existing.activeInstanceId||refreshed.activeInstanceId
    };
    Object.assign(existing,refreshed,preserved);
    existing.logs.unshift({id:id("log"),date:new Date().toISOString(),action:"Import",user:"AuditFlow",comment:`已按 ${source.sourceFile} 刷新导入评估；保留用户记录、附件与现场工作数据。`});
    return existing;
  }

