    const rawId = String(snapshot.id || project.id || MBEAL_ITMS_PROJECT_ID);
    const localId = MBEAL_ITMS_LEGACY_PROJECT_IDS.has(rawId) ? MBEAL_ITMS_PROJECT_ID : rawId;
