  function normaliseEnglishDisplay(value) {
    return String(value || "")
      .replace(/，/g, ", ")
      .replace(/。/g, ". ")
      .replace(/；/g, "; ")
      .replace(/：/g, ": ")
      .replace(/（/g, "(")
      .replace(/）/g, ")")
      .replace(/、/g, ", ")
      .replace(/\b(process|project|evidence|assessor|review|closure|requirement|work product|source|text)(target|strategy|plan|criteria|reference|record|rating|note|closure|confirmation)\b/gi, "$1 $2")
      .replace(/\s{2,}/g, " ")
      .replace(/\s+([,.;:!?])/g, "$1")
      .trim();
  }

  const ENGLISH_FIELD_FALLBACKS = Object.freeze({
    name: "Assessment project",
    title: "Assessment item",
    description: "Description requires assessor confirmation",
    criterion: "Assessment criterion requires assessor definition",
    reason: "Assessment rationale requires assessor verification",
    reviewerNote: "Assessor review note is required",
    mappingRationale: "Mapping rationale requires assessor calibration",
    impactScope: "Impact scope requires assessor definition",
    mappingClosureCriteria: "Closure verification criteria require assessor definition",
    closureRule: "Closure rule requires assessor definition",
    missingTypes: "Evidence gap requires assessor definition",
    closureEvidence: "Controlled closure evidence sample required",
    requiredEvidence: "Required evidence sample",
    interviewQuestions: "Assessor interview prompt required",
    solutionSteps: "Assessor action is required",
    workProduct: "Work product requires assessor confirmation",
    action: "Assessor action is required",
    opinion: "Assessment opinion requires assessor verification",
    claim: "Evidence-chain claim requires assessor verification",
    gapOrRisk: "Evidence gap requires assessor review",
    followUp: "Assessor follow-up is required",
    dimension: "Evidence dimension requires assessor verification",
    source: "Original-language evidence source",
    text: "Original-language assessor record",
    content: "Original-language evidence content",
    excerpt: "Original-language evidence excerpt"
  });

  function englishFallbackForKey(key, fallback = "", source = false) {
    const candidate = String(fallback == null ? "" : fallback).trim();
    if (candidate === "Untitled item" || candidate === "Untitled project") return "Assessment project";
    if (candidate && !CJK_TEXT.test(candidate)) return candidate;
    return ENGLISH_FIELD_FALLBACKS[key] || (source ? "Original-language evidence reference" : (candidate || "Assessment project"));
  }

  // This helper only prepares display values. It never writes translated text
  // into the workspace, so Chinese evidence and assessor records stay intact.
  function englishDisplayText(value, { source = false, fallback = "" } = {}) {
    const raw = String(value == null ? "" : value);
    if (currentLanguage() !== "en" || !raw) return raw;
    if (raw === "Untitled item" || raw === "Untitled project") return "Assessment project";
    if (ENGLISH_DISPLAY_NAME_EXACT[raw]) return ENGLISH_DISPLAY_NAME_EXACT[raw];
    const direct = window.AuditFlowI18n?.translateUi?.(raw) || raw;
    if (direct !== raw && direct !== "Untranslated interface text" && !CJK_TEXT.test(direct)) return normaliseEnglishDisplay(direct);
    // Imported assessment workbooks may carry a bilingual tail in one field.
    // Keep the source value unchanged, but show only the English segment in
    // the English view when an explicit Chinese marker is present.
    let output = raw
      .replace(/\s*(?:【中文说明】|\[中文说明\]|中文说明\s*[:：])[\s\S]*$/i, "")
      .replace(/\s*(?:【中文】|\[中文\]|中文\s*[:：])[\s\S]*$/i, "")
      .trim();
    ENGLISH_INLINE_REPLACEMENTS.forEach(([from, to]) => { output = output.split(from).join(to); });
    if (!CJK_TEXT.test(output)) return normaliseEnglishDisplay(output);
    const translated = window.AuditFlowI18n?.translateUi?.(output) || output;
    if (!CJK_TEXT.test(translated) && translated !== "Untranslated interface text") return normaliseEnglishDisplay(translated);
    return fallback || (source ? "Original-language evidence reference" : (raw || "Assessment project"));
  }

  function englishGeneratedIssueText(value) {
    const raw = String(value == null ? "" : value);
    const match = raw.match(/^(\S+)\s+已登记并与\s+([A-Z]+\.\d+)\s+关联[；;]\s*(.+?)[。.]?$/i);
    if (!match) return raw;
    const locator = match[3].replace(/[。.]$/, "");
    return `${match[1]} is registered against ${match[2]}; ${locator}.`;
  }

  function displayField(object, key, fallback = "") {
    return localizedField(object, key, object?.[key] ?? fallback);
  }

