  function englishToastText(value, fallback = "") {
    const raw = String(value == null ? "" : value).trim();
    if (!raw) return "";
    if (raw === "Untranslated interface text") return fallback;
    const mapped = ENGLISH_TOAST_FALLBACKS[raw];
    if (mapped) return mapped;
    if (!CJK_TEXT.test(raw)) return normaliseEnglishDisplay(raw);
    const translated = englishDisplayText(raw, { fallback: "" });
    if (translated && translated !== "Untranslated interface text" && !CJK_TEXT.test(translated)) return translated;
    return fallback;
  }

  function englishLocator(value) {
    return englishDisplayText(value, { source: true });
  }

  function evidenceStrengthText(value) {
    if (currentLanguage() !== "en") return String(value || "");
    return ({ direct: "Direct", corroborating: "Corroborating", "index-only": "Index-only" })[value] || englishDisplayText(value);
  }

  function localizedField(object, key, fallback = "") {
    const sourceField = ["content", "text", "excerpt"].includes(key);
    if (!object) {
      return currentLanguage() === "en"
        ? englishDisplayText(fallback, { source: sourceField, fallback: englishFallbackForKey(key, fallback, sourceField) })
        : fallback;
    }
    const source = object[key] ?? fallback;
    if (currentLanguage() !== "en") {
      const zhValue = object[`${key}Zh`];
      return zhValue !== undefined && zhValue !== null && String(zhValue).trim()
        ? zhValue
        : source;
    }
    if (object[`${key}En`]) return englishDisplayText(object[`${key}En`], { fallback: englishFallbackForKey(key, fallback, sourceField) });
    const text = String(source || "");
    if (key === "name" && ENGLISH_DISPLAY_NAME_EXACT[text]) return ENGLISH_DISPLAY_NAME_EXACT[text];
    if (key === "description" && text === "独立评估记录") return "Independent assessment record";
    // Older workspaces may not carry a dedicated English field. Use a display
    // conversion with an all-English fallback rather than partial word swaps.
    return englishDisplayText(text, { source: sourceField, fallback: englishFallbackForKey(key, fallback, sourceField) });
  }

  function localizedList(object, key) {
    const value = currentLanguage() === "en"
      ? (Array.isArray(object?.[`${key}En`]) ? object[`${key}En`] : object?.[key])
      : (Array.isArray(object?.[`${key}Zh`]) ? object[`${key}Zh`] : object?.[key]);
    if (!Array.isArray(value)) return [];
    return currentLanguage() === "en"
      ? value.map(item => englishDisplayText(item, { fallback: englishFallbackForKey(key) }))
      : value;
  }

  function localizedProject(project) {
    if(currentLanguage()!=="en"||!project)return project;
    const localize = (object, key, fallback = "") => ({ ...object, [key]: localizedField(object, key, object?.[key] ?? fallback) });
    const localizeEvidence = item => ({
      ...item,
      type: localizedField(item, "type", item.type),
      scope: localizedField(item, "scope", item.scope),
      structure: localizedField(item, "structure", item.structure),
      content: localizedField(item, "content", item.content),
      atomicItems: (item.atomicItems || []).map(atomic => ({ ...atomic, title: localizedField(atomic, "title", atomic.title), text: localizedField(atomic, "text", atomic.text) })),
      locators: (item.locators || []).map(locator => ({ ...locator, locator: englishLocator(locator.locator), excerpt: localizedField(locator, "excerpt", locator.excerpt) }))
    });
    const localizeAssessment = item => ({
      ...item,
      processName: localizedField(item, "processName", item.processName),
      title: localizedField(item, "title", item.title),
      criterion: localizedField(item, "criterion", item.criterion),
      reason: localizedField(item, "reason", item.reason),
      reviewerNote: localizedField(item, "reviewerNote", item.reviewerNote),
      mappingRationale: localizedField(item, "mappingRationale", item.mappingRationale),
      impactScope: localizedField(item, "impactScope", item.impactScope),
      mappingClosureCriteria: localizedField(item, "mappingClosureCriteria", item.mappingClosureCriteria),
      closureEvidence: localizedList(item, "closureEvidence"),
      requiredEvidence: localizedList(item, "requiredEvidence"),
      interviewQuestions: localizedList(item, "interviewQuestions"),
      evidenceSufficiency: item.evidenceSufficiency ? {
        ...item.evidenceSufficiency,
        missingTypes: localizedList(item.evidenceSufficiency, "missingTypes"),
        coveredTypes: localizedList(item.evidenceSufficiency, "coveredTypes")
      } : item.evidenceSufficiency,
      refs: (item.refs || []).map(ref => englishLocator(ref)),
      findings: (item.findings || []).map(finding => ({ ...finding, text: localizedField(finding, "text", finding.text) })),
      evidenceAnalysis: (item.evidenceAnalysis || []).map(evidence => ({ ...evidence, source: localizedField(evidence, "source", evidence.source), locator: englishLocator(evidence.locator), excerpt: localizedField(evidence, "excerpt", evidence.excerpt), claim: localizedField(evidence, "claim", evidence.claim), dimension: localizedField(evidence, "dimension", evidence.dimension) })),
      crossProcessAnalysis: (item.crossProcessAnalysis || []).map(relation => ({ ...relation, claim: localizedField(relation, "claim", relation.claim), gapOrRisk: localizedField(relation, "gapOrRisk", relation.gapOrRisk), followUp: localizedField(relation, "followUp", relation.followUp) }))
    });
    return {
      ...project,
      name: localizedField(project, "name", project.name),
      organization: localizedField(project, "organization", project.organization),
      product: localizedField(project, "product", project.product),
      aiOpinion: localizedField(project, "aiOpinion", project.aiOpinion),
      attributes: project.attributes ? { ...project.attributes, processContext: localizedField(project.attributes, "processContext", project.attributes.processContext) } : project.attributes,
      participants: (project.participants || []).map(participant => ({ ...participant, name: localizedField(participant, "name", participant.name), role: localizedField(participant, "role", participant.role) })),
      workspaces: (project.workspaces || []).map(workspace => ({ ...workspace, name: localizedField(workspace, "name", workspace.name), description: localizedField(workspace, "description", workspace.description) })),
      instances: (project.instances || []).map(instance => ({ ...instance, name: localizedField(instance, "name", instance.name) })),
      planCards: (project.planCards || []).map(card => localize(localize(localize(card, "title"), "description"), "notes")),
      sessions: (project.sessions || []).map(session => localize(localize(session, "title"), "notes")),
      evidence: (project.evidence || []).map(item => localizeEvidence({ ...item, name: localizedField(item, "name", item.name) })),
      assessments: (project.assessments || []).map(localizeAssessment),
      records: (project.records || []).map(record => ({ ...record, text: localizedField(record, "text", record.text), closureState: localizedField(record, "closureState", record.closureState) })),
      guidelines: (project.guidelines || []).map(guideline => ({ ...guideline, rule: localizedField(guideline, "rule", guideline.rule), comment: localizedField(guideline, "comment", guideline.comment) })),
      wbsIssues: (project.wbsIssues || []).map(issue => ({ ...issue, description: localizedField(issue, "description", issue.description), workProduct: localizedField(issue, "workProduct", issue.workProduct), action: localizedField(issue, "action", issue.action), opinion: localizedField(issue, "opinion", issue.opinion), closureEvidence: localizedList(issue, "closureEvidence"), solutionSteps: localizedList(issue, "solutionSteps") }))
    };
  }

