  renderCollaborationSettings = function renderCollaborationSettingsV111() {
    if (!cloudCollaborationMode()) {
      const endpoint = String(db.settings?.collaborationSyncUrl || DEFAULT_CLOUD_ENDPOINT).replace(/\/+$/, "");
      return `<section class="setting-section local-workspace-mode"><div class="section-title-row"><div><span class="overline">Remote collaboration</span><h2>Connect to the AuditFlow server</h2><p>This desktop workspace remains local until a server account is authenticated. Sign in below to load the same projects as the v12 web workbench.</p></div>${badge("info", "Not connected")}</div><form id="collaborationConfigForm" class="form-grid"><div class="form-field full"><label>Collaboration endpoint</label><input name="collaborationSyncUrl" type="url" value="${esc(endpoint)}" required placeholder="https://www.aspice-auditflow.cloud"></div><div class="form-field"><label>Server email</label><input name="remoteEmail" type="email" autocomplete="username" required placeholder="name@company.com"></div><div class="form-field"><label>Server password</label><input name="remotePassword" type="password" autocomplete="current-password" required></div><div class="form-field"><label>Workspace ID</label><input name="cloudWorkspaceId" value="${esc(db.settings?.cloudWorkspaceId || "AUDITFLOW-WEB")}" maxlength="160"></div><div class="form-field full"><label>Shared content policy</label><input value="Project representations, ratings, records and configuration sync; source attachment binaries and local AI/parsing preferences remain local." readonly></div><div class="page-actions full"><button type="button" class="btn secondary" data-action="test-collaboration">${icon("link")}Check server</button><button class="btn primary" data-action="save-collaboration">${icon("user")}Sign in and sync</button></div></form></section><section class="setting-section"><h2>Local workspace boundary</h2><p>Before server sign-in, this client keeps its local workspace available. Passwords are sent only to the configured server login endpoint and are not persisted by the client.</p></section>`;
    }
    const projects = [...(db.standardProjects || []), ...(db.customAudits || [])];
    const active = (db.collaboration?.presence || []).filter(item => Date.now() - new Date(item.lastSeen || item.expiresAt || 0).getTime() < 120000);
    const projectRows = projects.map(project => {
      const members = project.collaboration?.members || [];
      const roster = members.slice(0, 6).map(member => `<span class="member-chip" title="${esc(`${memberDisplayName(member)} · ${member.role || "Viewer"}`)}">${esc(memberDisplayName(member))}<small>${esc(member.role || "Viewer")}</small></span>`).join("") || `<span class="empty-mini">No membership record loaded yet.</span>`;
      const state = project.collaboration?.syncState || (project.collaboration?.remoteRevision ? "synced" : "connecting");
      return `<article class="collaboration-project-row"><header><div><strong>${esc(project.name || project.id)}</strong><small>${esc(project.id)} · shared revision r${Number(project.collaboration?.remoteRevision || 0)}</small></div>${badge(state === "conflict" ? "danger" : state === "synced" ? "success" : "info", state === "conflict" ? "Review required" : state === "synced" ? "Synchronized" : "Connecting")}</header><div class="collaboration-project-members">${roster}</div><div class="row-actions"><button type="button" class="btn secondary sm" data-action="refresh-collaboration" data-project="${esc(project.id)}">${icon("refresh")}Refresh</button>${["Lead Assessor", "Administrator"].includes(collaborationRole(project)) ? `<button type="button" class="btn secondary sm" data-action="sync-project-cloud" data-project="${esc(project.id)}">${icon("upload")}Sync now</button>` : ""}</div></article>`;
    }).join("") || `<div class="empty-mini">Loading shared projects from the collaboration service…</div>`;
    const roster = active.map(item => `<tr><td>${esc(item.userName || item.userId)}</td><td>${esc(item.projectName || item.projectId || "Shared project")}</td><td>${esc(item.phase || "editing")}</td><td>${formatDate(item.lastSeen || item.expiresAt)}</td></tr>`).join("") || `<tr><td colspan="4">No active collaborators reported in the last two minutes.</td></tr>`;
    return `<section class="setting-section collaboration-status-panel"><div class="section-title-row"><div><span class="overline">Shared collaboration</span><h2>Project collaboration</h2><p>Changes are checked every three seconds. Parsed document text, locators, tables, evidence items, scores, records, traceability and project configuration are shared. Original uploaded attachment binaries and local parsing/AI settings stay on the originating browser.</p></div>${badge("success", "3 s sync")}</div><form id="collaborationConfigForm" class="form-grid"><div class="form-field"><label>Collaboration endpoint</label><input name="collaborationSyncUrl" value="${esc(db.settings?.collaborationSyncUrl || DEFAULT_CLOUD_ENDPOINT)}" readonly></div><div class="form-field"><label>Workspace</label><input name="cloudWorkspaceId" value="${esc(db.settings?.cloudWorkspaceId || "AUDITFLOW-WEB")}" maxlength="160"></div><div class="form-field full"><label>Shared content policy</label><input value="Project document representations and configuration are shared; attachment binaries and local AI/parsing preferences remain local." readonly></div><div class="page-actions full"><button type="button" class="btn secondary" data-action="test-collaboration">${icon("link")}Check service</button><button type="button" class="btn secondary" data-action="refresh-collaboration" data-project="${esc(projects[0]?.id || "")}" ${projects.length ? "" : "disabled"}>${icon("refresh")}Refresh projects</button><button type="button" class="btn secondary" data-action="remote-logout">${icon("close")}Disconnect server</button><button type="button" class="btn primary" data-action="save-collaboration">${icon("check")}Save collaboration settings</button></div></form></section><section class="setting-section"><div class="section-title-row"><div><h2>Shared project access</h2><p>Roles and permissions are enforced by the service. Lead Assessors can update configuration and membership; AI suggestions remain advisory until an assessor reviews them.</p></div>${isAdministrator() ? `<button type="button" class="btn secondary sm" data-action="settings-tab" data-tab="admin">${icon("shield")}Administration</button>` : ""}</div><div class="collaboration-project-list">${projectRows}</div></section><section class="setting-section"><div class="section-title-row"><div><h2>Live collaborators</h2><p>Presence is a heartbeat, not a lock. Item-level locks only protect the BP/GP item currently being edited.</p></div>${badge("info", `${active.length} active`)}</div><div class="live-table-wrap"><table class="data-table"><thead><tr><th>Collaborator</th><th>Project</th><th>Area</th><th>Last heartbeat</th></tr></thead><tbody>${roster}</tbody></table></div></section>`;
  };

  function renderCodexSettings() {
    const s = db.settings || {};
    const connection = codexConnection || {};
    const portalUrl = connection.portalUrl || "https://llmcost.johnsonelectric.com/";
    const t = (zh, en) => uiText(zh, en);
    const model = s.codexModel || "";
    const provider = s.aiProvider || "johnson-electric";
    const protocol = s.aiProtocol || (provider === "deepseek" ? "chat-completions" : "responses");
    const fallbackRows = [[t("模型优先", "Model first"), t("存在有效 Virtual Key 时执行模型复核", "Run model review when a valid Virtual Key is available")], [t("本地规则回退", "Local-rule fallback"), t("服务不可用时自动输出可复核的本地候选结论", "Produce reviewable local candidates when the service is unavailable")], [t("密钥隔离", "Key isolation"), t("Virtual Key 仅保留在本机服务进程内存中", "Keep the Virtual Key only in the local service process memory")]];
    return `<section class="setting-section"><h2>DeepSeek / OpenAI-compatible API</h2><p>${t("本地 bridge 会使用 READY 探针验证地址、模型与 API Key。密钥只保存在本地 bridge 进程内存中；协作服务不会接收评估内容。", "The local bridge validates the endpoint, model, and API key with a READY probe. The key remains in local bridge process memory; the collaboration service never receives assessment content.")}</p>${codexConnectionCard()}<div class="page-actions" style="margin:14px 0"><a class="btn secondary" href="${esc(portalUrl)}" target="_blank" rel="noreferrer">${t("打开 API 控制台", "Open API console")}</a><button class="btn secondary" data-action="refresh-codex-status">${t("刷新本地配置状态", "Refresh local configuration status")}</button></div><form id="codexConfigForm"><div class="form-grid"><div class="form-field"><label>${t("AI 提供商", "AI provider")}</label><select name="aiProvider"><option value="johnson-electric" ${provider === "johnson-electric" ? "selected" : ""}>Johnson Electric</option><option value="deepseek" ${provider === "deepseek" ? "selected" : ""}>DeepSeek</option><option value="openai-compatible" ${provider === "openai-compatible" ? "selected" : ""}>OpenAI-compatible</option></select></div><div class="form-field"><label>${t("协议", "Protocol")}</label><select name="aiProtocol"><option value="responses" ${protocol === "responses" ? "selected" : ""}>Responses</option><option value="chat-completions" ${protocol === "chat-completions" ? "selected" : ""}>Chat Completions</option></select></div><div class="form-field full"><label>API Base URL</label><input name="codexBaseUrl" value="${esc(s.codexBaseUrl || (provider === "deepseek" ? "https://api.deepseek.com" : "https://llmcost.johnsonelectric.com/v1"))}" inputmode="url"><small>${t("DeepSeek 默认使用 https://api.deepseek.com；密钥只提交给本机 AI 服务。", "DeepSeek defaults to https://api.deepseek.com; the key is submitted only to the local AI service.")}</small></div><div class="form-field"><label>${t("模型（可选）", "Model (optional)")}</label><input name="codexModel" value="${esc(model)}" placeholder="${t("例如 deepseek-flash", "For example, deepseek-flash")}"></div><div class="form-field"><label>API Key</label><input name="virtualKey" type="password" autocomplete="off" placeholder="${t("仅提交给本机 AI 服务", "Submitted only to the local AI service")}"><small>${t("READY 探针失败时不会更新当前会话；成功后仅驻留于本机进程内存，服务重启后需重新配置。", "A failed READY probe does not replace the current session; on success, the key remains in local process memory and must be reconfigured after restart.")}</small></div></div><label class="switch-line"><span><strong>${t("检查本机 Codex / VS Code 状态", "Check local Codex / VS Code status")}</strong><p>${t("仅检查存在状态；不会读取、导出或显示登录令牌与配置内容。", "Only presence is checked; login tokens and configuration contents are never read, exported, or displayed.")}</p></span><input name="useLocalCodexConfig" type="checkbox" ${s.useLocalCodexConfig !== false ? "checked" : ""}><i></i></label><div class="page-actions" style="margin-top:16px"><button class="btn primary" data-action="save-codex-key">${t("验证并启用 API 会话", "Verify and enable API session")}</button><button type="button" class="btn ghost" data-action="clear-codex-key">${t("清除当前服务会话密钥", "Clear the current service-session key")}</button></div></form></section>${renderCopilotStudioSettings()}<section class="setting-section"><h2>${t("AI 降级策略", "AI fallback strategy")}</h2><p>${t("模型服务不可用时，AuditFlow 继续在前端完成本地规则评估，且不会显示中断性错误横幅。", "When the model service is unavailable, AuditFlow continues with local rule evaluation in the browser without an interrupting error banner.")}</p>${fallbackRows.map(item=>`<div class="switch-line"><div><strong>${item[0]}</strong><p>${item[1]}</p></div>${badge("success",t("启用", "Enabled"))}</div>`).join("")}</section>`;
  }

  function renderCopilotStudioSettings() {
    const t = (zh, en) => uiText(zh, en);
    const settings = db.settings || {};
    const status = copilotConnection || {};
    const ready = status.ready === true;
    const configured = status.configured === true;
    const agent = status.agent || {};
    const currentTransport = settings.codexChatTransport === "copilot-studio" ? "copilot-studio" : "local";
    const statusLabel = ready ? t("Agent 已连接", "Agent connected") : configured ? t("等待连接", "Configured, not ready") : t("未配置", "Not configured");
    const statusDetail = ready
      ? `${t("已发布代理", "Published agent")}: ${esc(agent.name || settings.copilotStudioAgentName || "—")} · ${esc(status.tokenEndpointHost || "")}`
      : t("配置状态只显示安全摘要，不返回或保存短期 Direct Line 凭据。", "Only safe connection metadata is shown; short-lived Direct Line credentials are never returned or stored.");
    return `<section class="setting-section copilot-studio-settings">
      <div class="section-title-row"><div><span class="overline">Microsoft Agents / Copilot Studio</span><h2>${t("连接已发布的 Copilot Studio Agent", "Connect a published Copilot Studio agent")}</h2><p>${t("本机 Microsoft 365 Copilot 桌面会话不能直接作为 JEAuditFlow API 使用。请发布 Copilot Studio agent，并配置由你的服务器托管的受控 token endpoint。", "A local Microsoft 365 Copilot desktop session is not a JEAuditFlow API. Publish a Copilot Studio agent and configure a controlled token endpoint hosted by your server.")}</p></div>${badge(ready ? "success" : configured ? "warn" : "neutral", statusLabel)}</div>
      <div class="switch-line"><div><strong>${t("连接状态", "Connection state")}</strong><p>${statusDetail}</p></div>${badge(ready ? "success" : "neutral", ready ? status.transport || "Copilot Studio" : t("待配置", "Not configured"))}</div>
      <form id="copilotStudioConfigForm">
        <div class="form-grid">
      <div class="form-field full"><label>${t("Token endpoint URL", "Token endpoint URL")}</label><input name="tokenEndpoint" type="url" inputmode="url" required value="${esc(settings.copilotStudioTokenEndpoint || "")}" placeholder="https://contoso.environment.api.powerplatform.com/powervirtualagents/botsbyschema/contoso_assessmentagent/directline/token?api-version=2022-03-01-preview"><small>${t("使用 Copilot Studio 已发布 Agent 的 Direct Line token endpoint。此处只保存 endpoint 与 Agent 元数据；短期 token 由服务端按需获取并保存在服务端进程内存。", "Use the Direct Line token endpoint for a published Copilot Studio agent. Only the endpoint URL and agent metadata are stored; short-lived tokens are fetched server-side and kept in service memory.")}</small></div>
          <div class="form-field"><label>${t("Agent 名称", "Agent name")}</label><input name="agentName" required value="${esc(settings.copilotStudioAgentName || agent.name || "")}"></div>
          <div class="form-field"><label>${t("Environment ID", "Environment ID")}</label><input name="environmentId" required value="${esc(settings.copilotStudioEnvironmentId || agent.environmentId || "")}"></div>
          <div class="form-field full"><label>${t("Schema name", "Schema name")}</label><input name="schemaName" required value="${esc(settings.copilotStudioSchemaName || agent.schemaName || "")}"></div>
          <div class="form-field"><label>${t("评估助手对话来源", "Assessment assistant chat source")}</label><select name="codexChatTransport"><option value="local" ${currentTransport === "local" ? "selected" : ""}>${t("本机 Codex / 当前模型", "Local Codex / current model")}</option><option value="copilot-studio" ${currentTransport === "copilot-studio" ? "selected" : ""} ${ready ? "" : "disabled"}>${t("已配置的 Copilot Studio Agent", "Configured Copilot Studio agent")}</option></select></div>
        </div>
        <div class="page-actions copilot-studio-actions"><button type="button" class="btn secondary" data-action="refresh-copilot-status">${icon("refresh")}${t("检查状态", "Check status")}</button><button type="button" class="btn secondary" data-action="save-copilot-transport">${t("保存对话来源", "Save chat source")}</button><button type="button" class="btn primary" data-action="configure-copilot">${icon("check")}${t("验证并连接 Agent", "Verify and connect agent")}</button><button type="button" class="btn ghost" data-action="clear-copilot">${t("清除服务端连接", "Clear server connection")}</button></div>
      </form>
    </section>`;
  }

  function renderCodexAssistantSettings() {
    const connection = codexConnection || {};
    const session = connection.session || {};
    const detected = connection.detected || {};
    const ready = !!session.providerReady;
    const endpoint = AuditFlowBackend?.webMode ? window.location.origin : String(db.settings?.codexBridgeUrl || "http://127.0.0.1:4173");
    const transport = session.transport === "codex-cli" ? "Codex CLI" : session.transport === "provider" ? "Virtual Key" : uiText("未就绪", "Not ready");
    const t = (zh, en) => uiText(zh, en);
    const statusLabel = ready ? t("本机会话可用", "Local session available") : t(codexConnection ? "等待本机会话" : "本机脚本离线", codexConnection ? "Waiting for local session" : "Local script offline");
    return `<section class="setting-section"><div class="section-title-row"><div><h2>${t("Codex 评估助手连接", "Codex Assessment Assistant connection")}</h2><p>${AuditFlowBackend?.webMode ? t("LAN 页面通过已认证的同源代理访问 /api/codex/status 和 /api/ai/opinion；浏览器不会直接访问本机回环端口。", "LAN pages use an authenticated same-origin proxy for /api/codex/status and /api/ai/opinion; the browser never calls a loopback port directly.") : t("项目整体评估与专业问答只调用用户电脑回环地址的 /api/codex/status 和 /api/ai/opinion。云协作服务不会收到对话和项目上下文。", "Project assessment and expert Q&A call only the local loopback /api/codex/status and /api/ai/opinion endpoints. Cloud collaboration never receives chat or project context.")}</p></div>${badge(ready ? "success" : codexConnection ? "warn" : "neutral", statusLabel)}</div><div class="switch-line"><div><strong>${t("本机连接脚本", "Local connection script")}</strong><p>${esc(endpoint)}</p></div>${badge(codexConnection ? "success" : "neutral", codexConnection ? t("API 可访问", "API reachable") : t("未连接", "Not connected"))}</div><div class="switch-line"><div><strong>Codex ${t("会话", "session")}</strong><p>${ready ? `${t("传输方式", "Transport")}: ${esc(transport)} · ${t("模型", "Model")}: ${esc(detected.model || session.model || t("由本机脚本决定", "Selected by local script"))}` : t("请在本机 Codex 中完成登录，或由本机服务配置 Virtual Key。", "Sign in to Codex on this computer, or configure a Virtual Key in the local service.")}</p></div>${badge(ready ? "success" : "warn", ready ? t("已就绪", "Ready") : t("待配置", "Needs configuration"))}</div><div class="page-actions" style="margin-top:16px"><button type="button" class="btn secondary" data-action="refresh-codex-status">${icon("sparkles")}${t("检查本机脚本", "Check local script")}</button><button type="button" class="btn primary" data-action="settings-tab" data-tab="codex">${icon("key")}${t("打开 Codex / Virtual Key", "Open Codex / Virtual Key")}</button><button type="button" class="btn secondary" data-action="global-codex-toggle">${icon("message")}${t("打开对话助手", "Open Codex chat")}</button></div></section>`;
  }

  function renderAiSettings() {
    const s = db.settings || {};
    const t = (zh, en) => uiText(zh, en);
    const bridgeEndpoint = AuditFlowBackend?.webMode ? window.location.origin : (s.codexBridgeUrl || "http://127.0.0.1:4173");
    const bridgeHelp = AuditFlowBackend?.webMode
      ? t("LAN 工作区使用已认证的同源代理；凭据只由本机服务读取，不保存在浏览器。", "LAN workspaces use an authenticated same-origin proxy; credentials are read only by the local service and never stored in the browser.")
      : t("仅接受 127.0.0.1、localhost 或 ::1。", "Only 127.0.0.1, localhost, or ::1 is accepted.");
    const boundaries = [["成员、角色和编辑锁", "Members, roles and edit locks"], ["文件解析与证据正文", "File parsing and evidence text"], ["评估计算与 Codex 对话", "Assessment calculations and Codex chat"], ["报告与工作区导出", "Reports and workspace exports"]];
    return `<section class="setting-section"><h2>${t("AI 与本地解析设置", "AI and local parsing")}</h2><p>${t("文件解析、BP/GP/PA 计算、报告、导出和 Codex 评估均在用户电脑执行。AI 只生成候选结论，不覆盖人工决定。", "File parsing, BP/GP/PA calculations, reports, exports, and Codex assessment run on this computer. AI only creates candidate conclusions and never overwrites human decisions.")}</p><form id="aiConfigForm"><div class="switch-line"><div><strong>${t("启用本机 Codex 复核", "Enable local Codex review")}</strong><p>${t("关闭后仅使用浏览器内置专业规则；不会影响人工审核、证据解析或本地报告。", "When disabled, built-in rules remain available and human review, evidence parsing, and local reports are unaffected.")}</p></div><label class="switch"><input name="aiEnabled" type="checkbox" ${s.aiEnabled ? "checked" : ""}><i></i></label></div><div class="form-grid" style="margin-top:17px"><div class="form-field full"><label>${t("本机 Codex 连接脚本", "Local Codex bridge")}</label><input name="codexBridgeUrl" value="${esc(bridgeEndpoint)}" placeholder="${esc(bridgeEndpoint)}" ${AuditFlowBackend?.webMode ? "readonly" : ""}><small>${bridgeHelp}</small></div></div><div class="page-actions" style="margin-top:16px"><button type="button" class="btn secondary" data-action="test-ai">${t("检查本机脚本", "Check local bridge")}</button><button class="btn primary" data-action="save-ai">${t("保存设置", "Save settings")}</button><button type="button" class="btn secondary" data-action="settings-tab" data-tab="codex">${t("配置 Codex", "Configure Codex")}</button><button type="button" class="btn secondary" data-action="global-codex-toggle">${icon("message")}${t("打开对话助手", "Open Codex chat")}</button></div></form></section>${renderCodexAssistantSettings()}<section class="setting-section local-workspace-mode"><h2>${t("数据边界", "Data boundary")}</h2>${boundaries.map(([zh, en]) => `<div class="switch-line"><div><strong>${t(zh, en)}</strong><p>${t("不发送到远端服务。", "Nothing is sent to a remote service.")}</p></div>${badge("success", t("本机", "Local"))}</div>`).join("")}</section>`;
  }

  function renderMcpSettings() {
    const english = currentLanguage() === "en";
    const t = (zh, en) => english ? en : zh;
    const metadata = ui.mcpStatus?.metadata || {};
    const tools = Array.isArray(metadata.capabilities?.tools) ? metadata.capabilities.tools : [];
    const online = ui.mcpStatus?.ok === true;
    const base = String(AuditFlowBackend.baseUrl || window.location.origin || "").replace(/\/+$/, "");
    return `<section class="setting-section mcp-settings">
      <div class="section-title-row"><div><span class="overline">Model Context Protocol</span><h2>${t("MCP Server for AI Assistants", "MCP Server for AI Assistants")}</h2><p>${t("让本地 Codex/Claude Code 等 AI Assistant 读取明确项目范围内的评估上下文，并通过受控工具修改云端项目文件与评估项配置。API Key 只由服务端环境变量管理，不保存在浏览器。", "Allow local Codex/Claude Code-style assistants to read explicitly scoped assessment context and use controlled tools to update cloud project documents and assessment configuration. API keys remain server environment configuration and are never stored in this browser.")}</p></div>${badge(online ? "success" : ui.mcpStatus ? "warn" : "neutral", online ? t("可访问", "Reachable") : t("未检查", "Not checked"))}</div>
      <div class="connection-metrics"><div><span>${t("端点", "Endpoint")}</span><strong>${esc(base + "/mcp")}</strong><small>HTTP + JSON-RPC 2.0</small></div><div><span>${t("认证", "Authentication")}</span><strong>X-API-KEY</strong><small>${t("服务端 API key 映射 AuditFlow 账号", "Server-side API key to AuditFlow account mapping")}</small></div><div><span>${t("项目范围", "Project scope")}</span><strong>${t("必填", "Required")}</strong><small>${t("每次项目工具调用必须携带 projectId", "Every project-scoped tool call must provide projectId")}</small></div></div>
      <div class="page-actions"><button class="btn primary" data-action="test-mcp">${icon("link")}${t("检查 MCP 服务", "Check MCP server")}</button><button class="btn secondary" data-action="copy-mcp-endpoint" data-endpoint="${esc(base + "/mcp")}">${icon("copy")}${t("复制端点", "Copy endpoint")}</button></div>
      ${ui.mcpStatus?.error ? `<div class="review-block danger"><strong>${t("检查失败", "Check failed")}</strong><p>${esc(ui.mcpStatus.error)}</p></div>` : ""}
    </section>
    <section class="setting-section"><div class="section-title-row"><div><h2>${t("可用工具", "Available tools")}</h2><p>${t("工具目录只显示能力名；详细输入 schema 通过 MCP tools/list 返回。", "The UI shows capability names; detailed input schemas are returned by MCP tools/list.")}</p></div>${badge("info", `${tools.length || "—"} ${t("项", "tools")}`)}</div><div class="check-grid">${(tools.length ? tools : ["initialize", "tools/list", "tools/call"]).map(tool => `<div class="switch-line"><div><strong>${esc(tool)}</strong><p>${tool === "tools/call" ? t("读取项目、评估项、文档、模板并执行受控候选写入。", "Read projects, assessment items, documents and templates, then perform controlled candidate writes.") : t("MCP 协议能力。", "MCP protocol capability.")}</p></div>${badge("success", t("受控", "Controlled"))}</div>`).join("")}</div></section>
    <section class="setting-section"><h2>${t("AI 边界", "AI boundary")}</h2>${[
      [t("允许", "Allowed"), t("读取项目和评估上下文；修改受控结构化文档；写入 AI Workspace Finding；更新 AI candidate 字段和评估指导配置。", "Read project and assessment context; edit controlled structured documents; create AI Workspace findings; update AI candidate fields and advisory assessment configuration.")],
      [t("禁止", "Not allowed"), t("静默改变正式 rating、确认 evidence、关闭 finding、批准 baseline 或绕过 assessor permission。", "Silently change formal ratings, confirm evidence, close findings, approve baselines or bypass assessor permissions.")],
      [t("并发控制", "Concurrency"), t("项目写入使用 expectedRevision；候选评估写入还必须持有 assessment lock，并写入 source=mcp 的审计事件。", "Writes use expectedRevision; assessment candidates also require an assessment lock and produce source=mcp audit events.")]
    ].map(([title, body]) => `<div class="switch-line"><div><strong>${title}</strong><p>${body}</p></div>${badge("success", t("强制", "Enforced"))}</div>`).join("")}</section>`;
  }

  function renderRecycleBinSettings() {
    const entries = Array.isArray(db.deletedProjects) ? db.deletedProjects : [];
    const permanent = ui.recycleBinTab === "purge";
    const english = currentLanguage() === "en";
    const t = (zh, en) => english ? en : zh;
    const tabButton = (tab, label, count) => `<button type="button" class="btn ${ui.recycleBinTab === tab ? "primary" : "secondary"} sm" data-action="recycle-bin-tab" data-tab="${tab}">${label}${count ? ` · ${count}` : ""}</button>`;
    const body = !entries.length ? `<div class="empty-state recycle-bin-empty"><div><span>${icon("trash")}</span><h2>${permanent ? t("没有可彻底删除的项目", "No projects ready for permanent deletion") : t("回收站为空", "Recycle bin is empty")}</h2><p>${t("移入回收站的审核项目会在这里保留，直到恢复或彻底删除。", "Audit projects moved to the recycle bin remain here until restored or permanently deleted.")}</p></div></div>` : entries.map(entry => {
      const project = entry.project || {};
      const name = english ? englishDisplayText(project.name || entry.projectId || "Assessment project", { fallback: "Assessment project" }) : project.name || entry.projectId || "未命名项目";
      return `<article class="recycle-bin-item"><div class="recycle-bin-item-main"><span class="recycle-bin-icon">${icon("trash")}</span><div><strong>${esc(name)}</strong><small>${esc(entry.projectId || project.id || "")} · ${t("删除于", "Deleted")} ${formatDate(entry.deletedAt)} · ${esc(entry.deletedBy || "AuditFlow")}</small></div></div><div class="row-actions">${permanent ? `<button class="btn danger sm" data-action="purge-deleted-project" data-id="${esc(entry.id)}">${icon("trash")}${t("彻底删除", "Delete permanently")}</button>` : `<button class="btn secondary sm" data-action="restore-deleted-project" data-id="${esc(entry.id)}">${icon("rotate")}${t("撤销删除", "Restore")}</button><button class="btn ghost sm" data-action="recycle-bin-tab" data-tab="purge">${t("彻底删除", "Delete permanently")}</button>`}</div></article>`;
    }).join("");
    return `<section class="setting-section recycle-bin-section"><div class="section-title-row"><div><h2>${t("项目回收站", "Project recycle bin")}</h2><p>${t("删除项目会先从当前审核状态移出并保留在本地回收站。恢复会保留原项目数据和审核记录；彻底删除不可撤销。", "Deleted projects are removed from active assessments and retained locally. Restoring preserves project data and audit records; permanent deletion cannot be undone.")}</p></div>${badge(entries.length ? "warn" : "success", `${entries.length} ${t("个项目", "projects")}`)}</div><div class="recycle-bin-tabs">${tabButton("deleted", t("已删除项目", "Deleted projects"), entries.length)}${tabButton("purge", t("彻底删除", "Permanent deletion"), entries.length)}</div><div class="recycle-bin-list">${body}</div></section>`;
  }

  function renderHelpCenterLegacy() {
    const step = (no, title, body) => `<article class="help-step"><span>${no}</span><div><strong>${esc(title)}</strong><p>${esc(body)}</p></div></article>`;
    const phase = (key, title, body) => `<div class="help-phase-row"><strong>${esc(title)}</strong><p>${esc(body)}</p></div>`;
    const faq = (q, a) => `<details class="help-faq"><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`;
    return `<section class="setting-section"><div class="section-title-row"><div><h2>评估师帮助中心</h2><p>面向 Automotive SPICE 4.0、功能安全和网络安全项目的本地优先审核工作指引。AuditFlow 先冻结正式范围，再登记证据、建立跨过程关系、生成 AI 初稿并由评估师确认；正式评级和安全结论始终由具备职责和独立性的审核员确认。</p></div><div class="help-intro-actions">${badge("info","ASPICE 4.0")}${badge("success","v7.4")}<a class="btn secondary sm" href="./help-manual.html" target="_blank" rel="noopener">${icon("help")}操作手册</a></div></div></section>
      <section class="setting-section"><h2>从范围到报告</h2><p class="help-section-intro">ASPICE 以“过程能力”评价项目，不以单个产品或文件作为评级对象。先锁定范围和目标，再建立证据链与结论闭环。</p><div class="help-steps">${[
        ["01","定义正式范围","在“ASPICE 评估”新建项目时，明确评估目的、目标能力等级和纳入评级的过程域。范围外过程可作为接口或治理背景，但不计入过程评级与报告结论。"],
        ["02","计划评估活动","在“计划和日程”落实过程实例、样本、评估师角色、访谈和里程碑。CL2 的绩效管理应能看到目标、计划、资源、监控调整和接口管理与 MAN.3 的对应关系。"],
        ["03","建立可定位的证据库","在“证据”登记工作产品并保留来源、版本/基线、责任、状态和原文定位。Helix 导出可辅助识别标识、追溯、变更和关闭字段，但不会替代原始证据。"],
        ["04","逐项实施 BP / GP 评估","在“执行”按正式范围内的 BP 与适用 GP 记录证据、访谈、发现和候选评级。AI 只提出候选；评估师应核对充分性、一致性和反证。"],
        ["05","验证追溯与跨过程闭环","在“追溯”确认需求、设计、验证结果以及问题和变更间的双向关系；将 MAN.3、SUP.1、SUP.8、SUP.9、SUP.10 作为治理和接口佐证。"],
        ["06","合并、复核、关闭","合并评估师记录并定稿，处理弱项与质量门禁后再关闭评估和导出报告。正式报告仅反映正式范围内、已人工复核的结论。"]].map(x=>step(x[0],x[1],x[2])).join("")}</div></section>
      <section class="setting-section"><h2>ASPICE 标准化审核配置</h2>
        <div class="review-block"><h3>项目、过程、能力三层对象</h3><p>评估对象通常是项目。项目先选择需要评估的过程域，再针对过程的过程属性（PA）形成能力结论。相关过程证据可揭示接口、配置、问题或变更风险，却不能替代被评过程的直接证据。</p></div>
        <div class="help-rating-grid"><div><strong>N</strong><span>未达成</span><small>0% - 15%</small></div><div><strong>P</strong><span>部分达成</span><small>&gt;15% - 50%</small></div><div><strong>L</strong><span>大部分达成</span><small>&gt;50% - 85%</small></div><div><strong>F</strong><span>完全达成</span><small>&gt;85% - 100%</small></div></div>
        <div class="review-block"><h3>AuditFlow 的能力边界</h3><p>本地引擎支持 CL1 / CL2 的证据驱动候选结论。CL1 关注 PA 1.1 的过程实施；CL2 还需 PA 2.1 绩效管理和 PA 2.2 工作产品管理。界面中的 N、P-、P、P+、L-、L、L+、F 是工作级细分，正式结论应按评估规则由评估师汇总。CL3 涉及组织标准过程与部署，本地引擎不输出 GP 3.x 评级。</p></div>
      </section>
      <section class="setting-section"><h2>九个评估流程</h2><div class="help-phases">${[
        ["01 总览","查看过程覆盖、证据解析、已确认追溯、人工复核、开放弱项和当前 BP/PA/GP 矩阵；将它作为评估准备度看板，而非最终评级。"],
        ["02 计划和日程","建立过程实例、样本策略、评估计划、访谈安排和责任分工，保证范围、计划和资源能够追溯。"],
        ["03 证据","导入 DOC/DOCX、PPTX、XLSX/XLSM、PDF、CSV、JSON、HTML 或文本；检查解析结果和证据定位，旧版 DOC 必须回原文核对。"],
        ["04 执行","以 Tree / Grid 逐项审查 BP / GP，记录客观证据、访谈问题、优势、弱项、建议与观察；评分依据须可回到证据。"],
        ["05 追溯","在 Trace Studio 把指标与证据关系标为 direct、corroborating 或 index-only；确认关系后再作为结论依据。"],
        ["06 合并","将多位评估师记录收敛到 Consolidated 工作区，处理分歧、重复与冲突证据，并确认最终记录。"],
        ["07 AI 评审","在“评定结果（BP + GP · AI 初稿，可复核改定）”中按过程与 PA 查看全部范围内候选，筛选待复核或证据缺口项，调整人工评分并进入核对详情维护理由、引用和 O/W/R。Codex 参考评审只读取已定稿记录并生成独立版本。"],
        ["08 版本","每次重新评估形成版本，可对比候选、发现和证据变化，避免把新证据覆盖为不可追溯的旧结论。"],
        ["09 关闭与报告","检查证据充分性、人工复核、未处理规则和弱项闭环；满足门禁后关闭并导出受控报告。"]].map(x=>phase(x[0],x[1],x[2])).join("")}</div></section>
      <section class="setting-section"><h2>功能安全与网络安全审核</h2><p>在“自定义审核”中使用内置生命周期模板：网络安全对应 ISO/SAE 21434:2021，功能安全对应 ISO 26262:2018。两类审核沿用 ASPICE 的操作节奏，但问题和工作产品按各自标准组织。</p><div class="help-phases">${[["范围与目标","冻结受审对象、标准版本、生命周期范围、假设和排除项。"],["计划与角色","配置安全负责人、架构师、审核员、项目经理、供应商和事件响应角色，落实里程碑与升级路径。"],["证据登记","上传安全计划、Item Definition、TARA/HARA、架构、FMEA/FTA/FMEDA、需求、验证、漏洞、发布和安全案例；解析失败或旧版 DOC 必须回原文核对。"],["AI 分析","按审核问题匹配直接证据、关联佐证和仅索引，执行四遍跨过程检查；AI 只形成候选评分、O/W/R、访谈问题和最小关闭证据。"],["人工复核","逐题回到原始材料核对版本、批准、代表性、独立性和闭环；人工改定后才成为当前版本结论。"],["关闭与报告","所有问题人工复核，证据无不足或部分充分，开放弱项处理完成，主审核员通过关闭门禁后再导出报告。" ]].map((item,index)=>phase(`${String(index+1).padStart(2,"0")} ${item[0]}`,item[0],item[1])).join("")}</div><div class="review-block"><h3>两类审核的关键工作产品</h3><p><strong>网络安全：</strong>治理与能力、Cybersecurity Plan、Item Definition、TARA、Cybersecurity Concept、技术安全需求、安全架构、验证确认、漏洞与事件响应、更新/退役和 Cybersecurity Case。</p><p><strong>功能安全：</strong>Safety Plan、Item Definition、HARA、Functional Safety Concept、技术安全需求/概念、系统/硬件/软件安全分析、V&amp;V、配置/变更、供应商、生产/服务/退役和 Safety Case。</p></div></section>
      <section class="setting-section"><h2>MAN.3 / SUP.8 支持域专项子项目</h2><p>当一次只需要核查项目管理或配置管理材料中的问题时，从审核总览或 ASPICE 评估项目列表点击“生成 MAN.3 / SUP.8 专项子项目”。该子项目是问题驱动的复核工作区，不生成未出现在上传文件中的整套 BP/GP，也不声明过程能力等级。</p><div class="help-steps">${[
        ["01","从父项目生成","在父项目行点击图层图标，选择 MAN.3、SUP.8 和需要继承的证据。父项目已有的 CEP Action Plan 问题会按所选过程自动带入，子项目会保留父项目 ID 和来源证据关系。"],
        ["02","上传实际问题文件","进入子项目“证据”页上传 DOCX、DOC、PDF、XLSX、CSV、JSON、HTML 或粘贴文本。系统按 Issue 编号、过程域、严重度/状态、原始问题、审核说明、风险、行动和最小关闭证据建立可定位的问题记录。"],
        ["03","识别并配对 BP/GP","点击“识别问题并配对 BP/GP”。AI/本地规则只对文件中真实识别出的 MAN.3 / SUP.8 问题生成评定项，并用标题、问题描述、风险、行动和关闭证据匹配候选 BP 与 GP。未出现的问题不进入列表。"],
        ["04","人工复核 AI 初稿","在“评定结果（BP + GP · AI 初稿，可复核改定）”逐条确认来源、定位、候选指标、评分、理由和最小关闭证据。问题清单本身只能证明缺口已被识别，不能代替项目计划、受控配置项、基线、状态账或关闭样本等直接实施证据。"],
        ["05","一键回写父项目","所有专项评定项完成人工复核后，点击“一键回写原项目”。系统向父项目追加草稿弱项、候选追溯关系和必要的新增证据，同时保留父项目已有人工评分、人工复核状态和正式范围；父项目范围外的指标只作为候选观察，不进入正式评级。"],
        ["06","按 ASPICE 门禁继续关闭","回写内容仍需在父项目中结合直接证据、评估师记录、访谈和质量门禁复核。专项子项目的“已回写”不等于父项目已关闭，也不等于 MAN.3 或 SUP.8 已达到某个能力等级。"]
      ].map(x=>step(x[0],x[1],x[2])).join("")}</div><div class="review-block"><h3>专项证据护栏</h3><p>Direct 证明目标过程实际执行且可定位；Corroborating 只证明上下游、SUP.1、SUP.8、SUP.9、SUP.10 或治理关系；Index-only 仅证明文件存在。没有目标过程直接证据时，不因问题文件或索引自动提高评分；F 仍只由评估师人工确认。</p></div></section>
      <section class="setting-section"><h2>证据与跨过程判定</h2>
        <div class="review-block"><h3>Direct - 直接证据</h3><p>目标过程内、可定位并直接证明某项 BP 或 GP 已实施的工作产品、记录或访谈事实。直接证据是评分的基础，需显示来源、版本、范围和关联指标。</p></div>
        <div class="review-block"><h3>Corroborating - 佐证</h3><p>上下游或支持过程对接口、一致性、配置、问题、变更和治理关系的支持信息。它可以提高结论可信度，但不能取代目标过程的直接实施证据。</p></div>
        <div class="review-block"><h3>Index-only - 仅索引</h3><p>仅表明文档、条目或链接存在，尚不能证明其内容、执行或结果满足指标。请补充可审阅内容和稳定定位后再提升证据作用。</p></div>
        <div class="review-block"><h3>必须检查的闭环</h3><p>对每个正式范围内过程，检查上游输入质量、下游使用与反馈，以及 MAN.3 的计划和纠正措施、SUP.1 的独立质量保证、SUP.8 的配置与基线、SUP.9 的问题关闭、SUP.10 的变更影响和验证。跨过程发现应记录为观察、风险、访谈问题或补证需求。</p></div>
      </section>
      <section class="setting-section"><h2>关闭、报告与数据</h2>
        <div class="review-block"><h3>关闭前必须满足</h3><p>所有 BP/GP 均已人工复核；证据充分性不存在 insufficient 或 partial；Guideline / TAA 没有未处理的 Broken；记录已定稿；弱项已关闭或已按评估约定形成受控处置。关闭后事件日志不可修改。</p></div>
        <div class="review-block"><h3>本地优先与 AI 边界</h3><p>证据在浏览器本地解析。默认不向外部 AI 发送内容；仅在配置企业网关和 Virtual Key 后执行模型复核。Virtual Key 只驻留本机服务内存，敏感项目可在“数据与隐私”关闭证据文本保留。</p></div>
        <div class="review-block"><h3>受控输出</h3><p>报告按正式范围过滤过程和评级矩阵。Word 导出包含目录字段，打开后使用 Ctrl+A 再按 F9 刷新页码；PDF 用于受控分发前请完成评估师复核。</p></div>
      </section>
      <section class="setting-section"><h2>常见问题</h2>${[
        ["为什么候选评级不能直接作为正式结论？","ASPICE 结论需要评估师判断证据的真实性、充分性、一致性和反证情况。AuditFlow 的本地规则和 AI 复核只提供可追溯的候选与补证方向。"],
        ["为什么有证据仍显示 N 或证据不足？","检查该证据是否属于正式范围内过程、是否可定位到 BP/GP、是否只证明文件存在，以及是否缺少执行结果、评审、配置或关闭记录。"],
        ["为什么关联过程不能提高目标过程的评级？","MAN.3、SUP.1、SUP.8、SUP.9、SUP.10 等可以证明治理和接口关系，但目标过程仍须由本过程的直接证据证明已实施。"],
        ["为什么本地引擎不自动给 F？","F 表示完全达成。AuditFlow 保留 F 给评估师依据多来源、跨周期且已闭环的直接证据作出最终确认。"],
        ["如何恢复演示数据？","设置 → 数据与隐私 → 恢复演示。该操作会清除当前浏览器中的改动，请先导出工作区备份。"],
        ["完整操作说明在哪里？","点击页面右上角问号，或使用本页顶部“操作手册”，可打开离线详细手册。"]].map(x=>faq(x[0],x[1])).join("")}</section>`;
  }

  function renderHelpCenterEnglish() {
    const step = (no, title, body) => `<article class="help-step"><span>${no}</span><div><strong>${esc(title)}</strong><p>${esc(body)}</p></div></article>`;
    const phase = (no, title, body) => `<div class="help-phase-row"><strong>${esc(no)} ${esc(title)}</strong><p>${esc(body)}</p></div>`;
    const faq = (question, answer) => `<details class="help-faq"><summary>${esc(question)}</summary><p>${esc(answer)}</p></details>`;
    return `<section class="setting-section"><div class="section-title-row"><div><h2>Assessor help center</h2><p>Local-first guidance for Automotive SPICE 4.0, functional-safety, and cybersecurity audits. Freeze formal scope, register evidence, build cross-process relationships, generate AI candidates, and keep the assessor in control of every formal conclusion.</p></div><div class="help-intro-actions">${badge("info", "ASPICE 4.0")}${badge("success", `v${APP_VERSION}`)}<a class="btn secondary sm" href="./help-manual.html" target="_blank" rel="noopener">${icon("help")}User manual</a></div></div></section>
      <section class="setting-section"><h2>From scope to report</h2><p class="help-section-intro">AuditFlow evaluates process capability from a traceable evidence chain. A file name, template, or link alone is never a formal implementation conclusion.</p><div class="help-steps">${[
        ["01", "Define formal scope", "Choose the assessment purpose, target capability level, and process areas that are formally rated. Related processes remain context only."],
        ["02", "Plan the assessment", "Set process instances, samples, assessor roles, interviews, milestones, and ownership in Plan & Schedule."],
        ["03", "Build a locatable evidence inventory", "Register source, version, owner, status, and stable page, sheet, row, or object locators. Helix exports assist discovery but never replace source evidence."],
        ["04", "Review BP and GP items", "Record objective evidence, interviews, findings, and candidate ratings for each in-scope indicator. AI remains advisory."],
        ["05", "Verify traceability and closure", "Confirm direct, corroborating, or index-only relationships and review upstream, downstream, MAN.3, SUP.1, SUP.8, SUP.9, and SUP.10 consistency."],
        ["06", "Consolidate, close, and report", "Finalise assessor records, resolve weaknesses and quality gates, then close the assessment and export a controlled report."]
      ].map(item => step(item[0], item[1], item[2])).join("")}</div></section>
      <section class="setting-section"><h2>Nine assessment phases</h2><div class="help-phases">${[
        ["01", "Overview", "Monitor process coverage, parsed evidence, confirmed trace links, human review, open weaknesses, and the BP/PA/GP matrix."],
        ["02", "Plan & Schedule", "Create process instances, sample strategy, assessment plans, interviews, milestones, and ownership."],
        ["03", "Evidence", "Import DOC/DOCX, PPTX, XLSX/XLSM, PDF, CSV, JSON, HTML, or text and verify parsing and locators."],
        ["04", "Conduct", "Review BP/GP items in Tree or Grid, maintain records, and keep every rating tied to evidence."],
        ["05", "Traceability", "Classify relationships as direct, corroborating, or index-only and confirm them against the source."],
        ["06", "Consolidate", "Resolve duplicate, conflicting, and incomplete assessor records in the controlled workspace."],
        ["07", "AI Review", "Use candidate ratings, evidence sufficiency, O/W/R findings, interview questions, and closure suggestions as review input only."],
        ["08", "Versions", "Compare evidence, candidate, finding, and review changes without overwriting the audit trail."],
        ["09", "Close & Report", "Check evidence sufficiency, human review, guideline state, weakness closure, and quality gates before export."]
      ].map(item => phase(item[0], item[1], item[2])).join("")}</div></section>
      <section class="setting-section"><h2>Evidence roles and AI boundary</h2><div class="review-block"><h3>Direct</h3><p>Locatable evidence from the target process that directly demonstrates implementation of the BP or GP.</p></div><div class="review-block"><h3>Corroborating</h3><p>Upstream, downstream, governance, configuration, problem, or change information that supports consistency but cannot replace target-process implementation evidence.</p></div><div class="review-block"><h3>Index-only</h3><p>A file, object, or link is known to exist, but its content, execution, and result are not yet verified.</p></div><div class="review-block"><h3>Human authority</h3><p>Local rules and Codex produce candidates and follow-up prompts. The assessor confirms scope, evidence role, rating, findings, and closure state.</p></div></section>
      <section class="setting-section"><h2>Local data and AI</h2><p>Projects, records, settings, evidence indexes, and attachments remain in the browser workspace. Files are parsed locally. A model request is made only after the user configures a local bridge or service, and Virtual Keys remain in the local service session.</p><div class="help-rating-grid"><div><strong>Local</strong><span>Browser workspace</span><small>Projects, evidence, records</small></div><div><strong>Candidate</strong><span>AI output</span><small>Requires assessor review</small></div><div><strong>Controlled</strong><span>Formal report</span><small>After quality gates</small></div></div></section>
      <section class="setting-section"><h2>Frequently asked questions</h2>${[
        ["Why cannot a candidate rating become a formal conclusion?", "ASPICE conclusions require assessor judgement of authenticity, sufficiency, consistency, and counter-evidence. AuditFlow supplies traceable candidates only."],
        ["Why does evidence still show a gap?", "Check that it belongs to the formal process scope, is locatable to the indicator, and proves execution, review, configuration, or closure rather than metadata alone."],
        ["Why can related-process evidence not raise the target rating?", "MAN.3, SUP.1, SUP.8, SUP.9, and SUP.10 can corroborate governance and interfaces, while the target process still needs its own direct implementation evidence."],
        ["How do I restore demo data?", "Open Settings, choose Data and privacy, then Restore demo. Export a workspace backup first because the reset removes local edits."],
        ["Where is the complete manual?", "Open the user manual link in this page or the question-mark button in the top navigation. The manual has a dedicated English path."]
      ].map(item => faq(item[0], item[1])).join("")}</section>`;
  }

  function renderHelpCenter() {
    if (currentLanguage() === "en") return renderHelpCenterEnglish();
    return renderHelpCenterLegacy()
      .replaceAll("v7.4", `v${APP_VERSION}`)
      .replaceAll("Vercel / Postgres", "ECS / MySQL")
      .replaceAll("Vercel/Postgres", "ECS/MySQL")
      .replaceAll("Vercel 同步", "服务器协作同步")
      .replaceAll("Vercel Functions、Postgres", "ECS Node 服务、MySQL");
  }

  function renderFeedback() {
    const entries = Array.isArray(db.feedbackEntries) ? db.feedbackEntries : [];
    const t = (zh, en) => uiText(zh, en);
    const count = `${entries.length} ${t("条", "entries")}`;
    return `<section class="setting-section"><div class="section-title-row"><div><h2>${t("反馈建议", "Feedback")}</h2><p>${t("先保存本机草稿，可添加截图、标注与隐私遮罩。只有预览后确认才会提交到当前站点。", "Save a local draft with screenshots, annotations and privacy masks. Submission to this site requires preview and confirmation.")}</p></div>${badge("info", count)}</div><button type="button" class="btn primary" data-action="open-feedback" data-source="settings">${icon("message")}${t("打开反馈", "Open feedback")}</button></section><section class="setting-section"><h2>${t("已保存的建议", "Saved feedback")}</h2>${entries.map(e => `<article class="feedback-item"><header><strong>${esc(e.feature)}</strong><time>${formatDate(e.createdAt || e.date)} · ${e.submission?.status === "submitted" ? t("已提交", "Submitted") : t("本地草稿", "Local draft")}</time></header><p>${esc(e.content)}</p><small>${(e.attachments || []).length} ${t("张图像", "images")}${e.attachmentName ? ` · ${esc(e.attachmentName)}` : ""}</small></article>`).join("") || `<div class="empty-mini">${t("还没有本机反馈。", "No local feedback yet.")}</div>`}</section>`;
  }

  function renderSettings() {
    stopSettingsTraffic();
    app.innerHTML = `<div class="page">${renderPageHead("Workspace Settings", uiText("账户、AI 与本地解析设置", "Account, AI and local parsing settings"), uiText("管理账户访问、共享项目权限、AI 模型、Helix 表格识别规则和本地数据策略。", "Manage account access, shared-project permissions, AI models, Helix table-recognition rules, and local data policy."), "")}<div class="settings-layout">${settingsNav()}<div>${settingsContent()}</div></div></div>`;
    if (ui.settingsTab === "monitor") startSettingsTraffic();
  }

  function assessmentGateState(project) {
    const broken = (project.guidelines || []).filter(item => item.state === "broken" && !item.handled).length;
    const drafts = (project.records || []).filter(item => item.status !== "Final").length;
    const weaknesses = (project.records || []).filter(item => item.type === "weakness");
    const openWeakness = weaknesses.filter(item => item.closureState !== "已关闭" && item.closureState !== "Closed").length;
    const quality = assessmentQuality(project);
    const blockers = assessmentBlockerTree(project);
    return { broken, drafts, weaknesses, openWeakness, closedWeaknesses: weaknesses.length - openWeakness, quality, blockers, gatePass: !blockers.length && quality.ready };
  }

  function renderCloseAssessment(project) {
    const gate=assessmentGateState(project);
    return `<header class="trace-view-header"><div><span class="overline">Controlled assessment state</span><h2>${uiText("关闭评估", "Close Assessment")}</h2><p>${uiText("关闭会冻结当前正式结论并写入不可修改日志；证据、记录、弱项和人工复核必须先形成闭环。", "Closure freezes the current formal conclusion and writes an immutable log. Evidence, records, weaknesses, and assessor reviews must first be closed.")}</p></div></header><section class="quality-gate ${gate.gatePass?"pass":"block"}"><span>${icon(gate.gatePass?"check":"alert")}</span><div><strong>${gate.gatePass?uiText("质量门禁通过，可关闭评估", "Quality gate passed; assessment may be closed"):uiText("关闭前仍有阻塞项", "Closure is blocked")}</strong><p>${gate.drafts} ${uiText("条记录未定稿", "draft records")} · ${gate.openWeakness} ${uiText("条弱项未关闭", "open weaknesses")} · ${gate.broken} Guideline · ${gate.quality.unreviewed} ${uiText("项未复核", "unreviewed")}</p></div>${project.assessmentState==="Closed"?`<button class="btn secondary" data-action="reopen-assessment" data-id="${project.id}">${uiText("重新打开", "Reopen")}</button>`:`<button class="btn primary" data-action="close-assessment" data-id="${project.id}" ${gate.gatePass?"":"disabled"}>${uiText("关闭评估", "Close Assessment")}</button>`}</section>${renderAssessmentReadiness(project)}<div class="close-assessment-grid"><section class="setting-section"><div class="section-title-row"><div><h2>${uiText("不可修改的评估日志", "Immutable assessment log")}</h2><p>Open、Close、Import ${uiText("和评估师评论形成状态追踪记录。", "and assessor comments form the state trail.")}</p></div><button class="btn secondary sm" data-action="add-log-comment" data-id="${project.id}">${icon("plus")}${uiText("添加评论", "Add comment")}</button></div><div class="live-table-wrap"><table class="data-table"><thead><tr><th>${uiText("时间", "Time")}</th><th>${uiText("动作", "Action")}</th><th>${uiText("用户", "User")}</th><th>${uiText("内容", "Comment")}</th></tr></thead><tbody>${(project.logs||[]).map(item=>`<tr><td>${formatDate(item.date)}</td><td>${badge(item.action==="Close"?"success":item.action==="Open"?"info":"neutral",item.action)}</td><td>${esc(item.user)}</td><td>${esc(item.comment)}</td></tr>`).join("")}</tbody></table></div></section><aside><section class="panel"><header class="panel-head"><div><h2>${uiText("整改闭环", "Finding closure")}</h2><p>SUP.9 → SUP.10 → ${uiText("工作产品更新 → 验证 → SUP.8 基线", "work-product update → verification → SUP.8 baseline")}</p></div></header><div class="panel-body info-list"><div class="info-row"><span>${uiText("弱项记录", "Weaknesses")}</span><strong>${gate.weaknesses.length}</strong></div><div class="info-row"><span>${uiText("已验证关闭", "Verified closed")}</span><strong>${gate.closedWeaknesses}</strong></div><div class="info-row"><span>${uiText("仍需关闭", "Open")}</span><strong>${gate.openWeakness}</strong></div><button class="btn secondary" data-action="open-consolidation" data-id="${project.id}">${icon("check")}${uiText("进入记录合并", "Open consolidation")}</button></div></section></aside></div>`;
  }

  // ── Codex assistant (v7.6.1) ──────────────────────────────────────────
  function recordOperation(project, action, detail) {
    const operation = { id: id("op"), date: new Date().toISOString(), action, detail, user: project.owner || "AuditFlow" };
    project.operationLog ||= [];
    project.operationLog.unshift(operation);
    return operation;
  }

  function buildCodexProjectContext(project) {
    const gate = assessmentGateState(project);
    const quality = assessmentQuality(project);
    const trace = traceCoverage(project);
    const evidence = project.evidence || [];
    const assessments = project.assessments || [];
    const records = project.records || [];
    const parsed = evidence.filter(item => item.parseStatus === "parsed").length;
    const lines = [
      `Project: ${project.id || "—"} · ${project.name || "—"}`,
      `Organisation: ${project.organization || "—"} · Product: ${project.product || "—"}`,
      `PAM: ${project.pam || "—"} · State: ${project.assessmentState || project.status || "—"}`,
      `Formal scope: ${(project.processes || []).join(", ") || "not configured"}`,
      `Target level: ${project.targetLevel || "—"} · Achieved level: ${project.achievedLevel || achievedLevel(project) || "—"}`,
      "",
      "PROCESS CAPABILITY",
      ...(project.processes || []).map(process => `${process}: L${processCapability(project, process)} · PA1.1=${processPaRating(project, process, "PA 1.1")} · PA2.1=${processPaRating(project, process, "PA 2.1")} · PA2.2=${processPaRating(project, process, "PA 2.2")}`),
      "",
      "EVIDENCE AND TRACEABILITY",
      `${evidence.length} evidence files (${parsed} parsed); ${trace.linked}/${trace.total} indicators linked; direct coverage ${trace.directPercent}%; ${trace.confirmed} assessor-confirmed links.`,
      `BP/GP items: ${assessments.length}; reviewed ${assessments.filter(item => item.reviewed).length}; insufficient ${quality.insufficient}; partial ${quality.partial}; low confidence ${quality.lowConfidence}.`,
      `Records: strengths ${records.filter(item => item.type === "strength").length}; weaknesses ${records.filter(item => item.type === "weakness").length}; recommendations ${records.filter(item => item.type === "recommendation").length}; drafts ${gate.drafts}; open weaknesses ${gate.openWeakness}.`,
      `Closure gate: ${gate.gatePass ? "pass" : "blocked"}; unreviewed ${quality.unreviewed}; unresolved guidelines ${gate.broken}.`,
      "",
      "Use this snapshot as advisory context. Separate evidence-supported facts, inferences, and evidence still required. Formal ratings remain with the assessor."
    ];
    return lines.join("\n");
  }

  function codexAssistantHistoryFor(project) {
    if (codexAssistantChat.projectId !== project.id) {
      codexAssistantChat.projectId = project.id;
      codexAssistantChat.messages = window.CodexAssistant?.loadHistory(project.id) || [];
    }
    return codexAssistantChat.messages;
  }

  function codexAssistantMarkdown(text) {
    const source = String(text || "");
    return source.split("\n").map(line => {
      const escaped = esc(line);
      if (/^#{1,4}\s/.test(line)) return `<h4 class="codex-md-h">${escaped.replace(/^#{1,4}\s*/, "")}</h4>`;
      if (/^[-*]\s/.test(line)) return `<li>${escaped.replace(/^[-*]\s*/, "")}</li>`;
      return escaped ? `<p>${escaped.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>").replace(/`([^`]+)`/g, "<code>$1</code>")}</p>` : "";
    }).join("");
  }

  function codexAssistantWelcomeBubble() {
    return `<article class="codex-bubble assistant"><header>Codex</header><div class="codex-bubble-body"><p>${esc(uiText("你好，我是 Codex ASPICE 评估助手。可以直接提问 BP/GP 解读、评级门禁、证据充分性和关闭证据。", "Hi, I am the Codex ASPICE assessment assistant. Ask about BP/GP interpretation, rating gates, evidence sufficiency, or closure evidence."))}</p></div></article>`;
  }

  function codexAssistantReviewBasis(project, runContext, processScope = project?.processes) {
    const scope = [...new Set((Array.isArray(runContext?.processCodes) ? runContext.processCodes : processScope || []).map(value => String(value || "").trim()).filter(Boolean))].slice(0, 32);
    const scopeSet = new Set(scope);
    const indicators = [...new Set((Array.isArray(runContext?.assessmentRefs) ? runContext.assessmentRefs : []).map(value => String(value || "").trim()).filter(Boolean))].slice(0, 24);
    const evidenceRefs = (Array.isArray(runContext?.evidenceRefs) ? runContext.evidenceRefs : []).slice(0, 12).map(item => ({
      code: String(item?.code || item?.id || "").trim().slice(0, 96),
      locator: String(item?.locator || "").trim().slice(0, 180),
      role: ["direct", "corroborating", "index-only"].includes(item?.role) ? item.role : "index-only",
      process: String(item?.process || "").trim().slice(0, 48),
      indicator: String(item?.indicator || "").trim().slice(0, 96)
    })).filter(item => item.code);
    const gaps = (Array.isArray(project?.assessments) ? project.assessments : [])
      .filter(item => item && scopeSet.has(String(item.process || "")))
      .flatMap(item => {
        const missingTypes = currentLanguage() === "en"
          ? item.evidenceSufficiency?.missingTypesEn || item.evidenceSufficiency?.missingTypes
          : item.evidenceSufficiency?.missingTypes;
        const missing = Array.isArray(missingTypes) ? missingTypes : [];
        const findings = Array.isArray(item.findings) ? item.findings : [];
        return [
          ...missing.map(value => `${item.process}.${item.code || ""}: ${String(value || "").trim()}`),
          ...findings.map(value => String(value?.textEn && currentLanguage() === "en" ? value.textEn : value?.text || "").trim())
        ];
      })
      .filter(Boolean)
      .slice(0, 6)
      .map(value => value.slice(0, 220));
    return {
      project: `${String(project?.id || "").trim()} · ${String(localizedField(project, "name", project?.name || "") || "").trim()}`.slice(0, 220),
      scope,
      indicators,
      evidenceRefs,
      gaps,
      guardrails: [
        uiText("范围外过程不参与评级；关联过程资料只作佐证。", "Out-of-scope processes are not rated; related-process material is corroborating only."),
        uiText("缺少直接证据时不得推定符合；所有 AI 结论均为候选，正式评分和关闭由评估师确认。", "Do not infer conformity without direct evidence; AI conclusions are candidates, and formal ratings and closure require assessor confirmation.")
      ]
    };
  }

  function codexAssistantReviewBasisMarkup(basis) {
    if (!basis) return "";
    const evidence = basis.evidenceRefs?.length
      ? `<ul>${basis.evidenceRefs.map(item => `<li><strong>${esc(item.code)}</strong><span>${esc([item.locator, item.role, item.process, item.indicator].filter(Boolean).join(" · "))}</span></li>`).join("")}</ul>`
      : `<p>${uiText("本次请求未包含结构化证据引用。", "No structured evidence references were included in this request.")}</p>`;
    const gaps = basis.gaps?.length
      ? `<ul>${basis.gaps.map(item => `<li>${esc(item)}</li>`).join("")}</ul>`
      : `<p>${uiText("所选正式范围内没有已记录的结构化缺口字段。", "No structured gap fields are recorded in the selected formal scope.")}</p>`;
    return `<details class="codex-review-basis"><summary>${uiText("评估依据摘要", "Assessment basis summary")}</summary><div class="codex-review-basis-body"><div class="codex-review-basis-row"><strong>${uiText("项目", "Project")}</strong><span>${esc(basis.project || "—")}</span></div><div class="codex-review-basis-row"><strong>${uiText("正式过程范围", "Formal process scope")}</strong><span>${esc((basis.scope || []).join(", ") || "—")}</span></div><div class="codex-review-basis-row"><strong>${uiText("涉及指标", "Indicators in context")}</strong><span>${esc((basis.indicators || []).join(", ") || "—")}</span></div><section><h4>${uiText("输入证据引用与角色", "Input evidence references and roles")}</h4>${evidence}</section><section><h4>${uiText("项目中已记录的缺口", "Gaps recorded in the project")}</h4>${gaps}</section><section><h4>${uiText("评估边界", "Assessment boundaries")}</h4><ul>${(basis.guardrails || []).map(item => `<li>${esc(item)}</li>`).join("")}</ul></section><p class="codex-review-basis-note">${uiText("此摘要列出结构化输入与规则边界，不是模型隐藏推理链。", "This summary lists structured inputs and guardrails; it is not the model's private reasoning.")}</p></div></details>`;
  }

  function codexAssistantBubble(message) {
    const user = message.role === "user";
    return `<article class="codex-bubble ${user ? "user" : "assistant"}"><header>${user ? esc(uiText("评估员", "Assessor")) : "Codex"}</header><div class="codex-bubble-body">${codexAssistantMarkdown(message.content)}</div>${user ? "" : codexAssistantReviewBasisMarkup(message.reviewBasis)}</article>`;
  }

  function codexAssistantErrorMessage(error) {
    if (error?.code === "aborted" || error?.name === "AbortError") return uiText("请求已取消", "Request cancelled");
    return String(error?.message || uiText("未知错误", "Unknown error"));
  }

  async function codexAssistantSend(project, userText) {
    const assistant = window.CodexAssistant;
    const text = String(userText || "").trim();
    if (!assistant || !project || !text || codexAssistantChat.busy) return;
    if (!requireCollaborationRole(project, ["Lead Assessor", "Assessor"], "使用 Codex 评估助手")) return;
    const history = codexAssistantHistoryFor(project);
    history.push({ role: "user", content: text });
    assistant.saveHistory(project.id, history);
    const log = document.getElementById("codexChatLog");
    if (log) log.insertAdjacentHTML("beforeend", codexAssistantBubble({ role: "user", content: text }) + `<article class="codex-bubble assistant" id="codexStreaming"><header>Codex</header><div class="codex-bubble-body"><span class="codex-typing">${esc(uiText("正在思考…", "Thinking…"))}</span></div></article>`);
    const input = document.getElementById("codexChatInput");
    if (input) input.value = "";
    codexAssistantChat.busy = true;
    codexAssistantChat.lastHarnessRunId = "";
    try {
      const controller = new AbortController();
      codexAssistantChat.controller = controller;
      const allowedProcesses = collaborationProcessScopes(project).includes("*")
        ? project.processes
        : project.processes.filter(process => collaborationProcessScopes(project).includes(process));
      const structuredContext = assistant.buildProjectContext
        ? assistant.buildProjectContext(
          project,
          codexAssistantChat.attachments || [],
          allowedProcesses
        )
        : { contextText: "", runContext: { projectId: project.id } };
      const contextText = [
        buildCodexProjectContext(project),
        "",
        "STRUCTURED BP/GP, FINDING, EVIDENCE AND UPLOAD REFERENCES",
        structuredContext.contextText
      ].join("\n");
      const full = await assistant.chat({
        messages: [{ role: "system", content: assistant.systemPrompt(contextText) }, ...history.slice(-24)],
        runContext: structuredContext.runContext,
        transport: db.settings?.codexChatTransport === "copilot-studio" ? "copilot-studio" : "local",
        signal: controller.signal,
        onDelta: (_delta, output) => { const body = document.querySelector("#codexStreaming .codex-bubble-body"); if (body) body.innerHTML = codexAssistantMarkdown(output); }
      });
      const content = String(typeof full === "string" ? full : full?.content || "").trim();
      if (!content || content === "Untranslated interface text") throw new Error(uiText("Codex 未返回可用内容。", "Codex returned no usable content."));
      codexAssistantChat.lastHarnessRunId = typeof full === "object" ? String(full.harnessRunId || "") : "";
      const reviewBasis = codexAssistantReviewBasis(project, structuredContext.runContext, allowedProcesses);
      history.push({ role: "assistant", content, runId: codexAssistantChat.lastHarnessRunId || "", reviewBasis });
      assistant.saveHistory(project.id, history);
      const streaming = document.getElementById("codexStreaming");
      if (streaming) streaming.insertAdjacentHTML("beforeend", codexAssistantReviewBasisMarkup(reviewBasis));
      codexAssistantChat.attachments = [];
    } catch (error) {
      const body = document.querySelector("#codexStreaming .codex-bubble-body");
      if (body) body.innerHTML = `<div class="codex-error">${icon("alert")}${esc(codexAssistantErrorMessage(error))}</div>`;
      toast(uiText("Codex 请求失败", "Codex request failed"), codexAssistantErrorMessage(error), "warn");
    } finally {
      codexAssistantChat.busy = false;
      codexAssistantChat.controller = null;
      document.getElementById("codexStreaming")?.removeAttribute("id");
    }
  }

  function codexAssistantOverall(project) {
    const prompt = currentLanguage() === "en"
      ? "Review this project as a senior Automotive SPICE assessor. Summarise scope, capability, evidence gaps, risks, closure readiness, and next actions. Distinguish facts, inferences, and evidence still required. Do not issue a formal certification conclusion."
      : "请以资深 Automotive SPICE 评估师身份评审当前项目，概述范围、能力、证据缺口、风险、关闭准备度和下一步行动。区分事实、推断和仍需补充的证据，不要给出正式认证结论。";
    codexAssistantSend(project, prompt);
  }

  async function parseCodexAttachments(files) {
    const parsed = [];
    for (const file of [...(files || [])].filter(item => item && item.size < 10 * 1024 * 1024)) {
      try {
        const result = await parseEvidenceFile(file);
        const text = String(result?.text || result?.content || "").slice(0, 24000);
        parsed.push({ id: id("CODEX-FILE"), name: file.name, size: file.size, type: file.type, parseStatus: "parsed", text, atomicItems: result?.items || [] });
      } catch (error) {
        parsed.push({ id: id("CODEX-FILE"), name: file.name, size: file.size, type: file.type, parseStatus: "failed", text: "", atomicItems: [] });
      }
    }
    codexAssistantChat.attachments = [...(codexAssistantChat.attachments || []), ...parsed];
    renderGlobalCodexAssistant();
  }

  async function importCodexAttachments(project) {
    const attachments = codexAssistantChat.attachments || [];
    if (!project || !attachments.length) return;
    const files = attachments.map(item => new File([item.text || ""], item.name, { type: item.type || "text/plain" }));
    ui.evidenceTarget = { type: "standard", id: project.id };
    await handleEvidenceFiles(files, { source: "Codex Assistant local upload" });
    codexAssistantChat.attachments = [];
    renderGlobalCodexAssistant();
  }

  function renderCodexAssistantPanel(project) {
    const connection = codexConnection || {};
    const copilotReady = db.settings?.codexChatTransport === "copilot-studio" && copilotConnection?.ready === true;
    const ready = !!connection.session?.providerReady || copilotReady;
    const transportLabel = copilotReady ? "Copilot Studio" : connection.session?.transport === "codex-cli" ? "Codex CLI" : connection.session?.transport === "provider" ? "Provider" : uiText("未就绪", "Not ready");
    const history = codexAssistantHistoryFor(project);
    const attachments = codexAssistantChat.attachments || [];
    const attachmentMarkup = attachments.length ? `<div class="codex-attachment-list" id="codexAttachmentList">${attachments.map(item => `<article><span>${icon("file")}</span><div><strong>${esc(item.name)}</strong><small>${formatSize(item.size || 0)}</small></div><button type="button" class="action-icon" data-action="remove-codex-attachment" data-attachment="${esc(item.id)}" title="${uiText("移除附件", "Remove attachment")}">${icon("close")}</button></article>`).join("")}</div>` : "";
    const options = visibleStandardProjects().map(item => `<option value="${esc(item.id)}" ${item.id === project.id ? "selected" : ""}>${esc(item.id)} · ${esc(localizedField(item, "name", item.name))}</option>`).join("");
    return `<section class="codex-assistant-panel" id="codexAssistantPanel"><header class="codex-assistant-head"><div class="codex-assistant-title"><span class="codex-assistant-logo"><img src="./icons/codex-assistant-flow-32.png" alt=""></span><div><span class="overline">Codex · ASPICE Assessor Copilot</span><h2>${uiText("Codex 评估助手", "Codex Assessment Assistant")}</h2></div></div><div class="codex-assistant-actions"><label class="codex-project-picker"><span>${uiText("项目", "Project")}</span><select data-codex-project>${options}</select></label>${ready ? badge("success", `${uiText("已就绪", "Ready")} · ${transportLabel}`) : badge("warn", uiText("本机会话待登录", "Local session sign-in required"))}<button class="btn secondary sm" data-action="open-codex-settings">${icon("key")}${uiText("连接设置", "Connection settings")}</button><button class="btn primary sm" data-action="codex-overall" data-id="${esc(project.id)}" data-codex-busy>${icon("sparkles")}${uiText("Codex 整体评估", "Codex overall assessment")}</button><button class="btn ghost sm" data-action="codex-clear" data-id="${esc(project.id)}" data-codex-busy>${icon("trash")}${uiText("清空对话", "Clear chat")}</button></div></header><div class="codex-chat-log" id="codexChatLog">${history.length ? history.map(codexAssistantBubble).join("") : codexAssistantWelcomeBubble()}</div><form class="codex-chat-input" id="codexChatForm" data-project="${esc(project.id)}">${attachmentMarkup}<div class="codex-upload-actions"><input type="file" id="codexAttachmentPicker" hidden multiple accept=".pdf,.doc,.docx,.pptx,.xlsx,.xlsm,.txt,.md,.csv,.json,.html"><button type="button" class="btn secondary sm" data-action="pick-codex-attachment">${icon("upload")}${uiText("上传文件", "Upload files")}</button>${attachments.length ? `<button type="button" class="btn secondary sm" data-action="codex-import-attachments" data-id="${esc(project.id)}">${icon("plus")}${uiText("加入证据清单", "Add to evidence inventory")}</button>` : ""}</div><small class="codex-upload-disclosure">${uiText("发送时，已上传资料及其定位摘录会交给当前配置的模型提供方；运行历史仅保存评估轨迹和引用，不保存资料全文或模型思维链。", "On send, uploaded excerpts and locators are shared with the configured model provider; run history stores audit references only, never full source text or private reasoning.")}</small><textarea id="codexChatInput" rows="5" placeholder="${esc(uiText("向 Codex 提问 ASPICE 问题…", "Ask an ASPICE question…"))}"></textarea><button type="submit" class="btn primary" data-action="codex-send" data-id="${esc(project.id)}">${icon("send")}${uiText("发送", "Send")}</button></form><footer class="codex-assistant-foot">${uiText("Codex 输出为 AI 参考意见，不等同于正式评估结论；正式评级与关闭仍由评估师确认。", "Codex output is an AI reference opinion, not a formal assessment conclusion; ratings and closure still require assessor confirmation.")}</footer></section>`;
  }

  function globalCodexProject() {
    const route = parseRoute();
    const routeId = route[0] === "standard" ? (route[1] === "report" ? route[2] : route[1]) : "";
    return visibleStandardProjects().find(project => project.id === routeId) || visibleStandardProjects().find(project => project.id === (ui.codexAssistantProjectId || db.settings.lastAssistantProjectId)) || visibleStandardProjects()[0] || null;
  }

  function renderGlobalCodexAssistant() {
    const project = globalCodexProject();
    const label = uiText("打开 Codex 评估助手", "Open Codex Assessment Assistant");
    if (codexAssistantTrigger) {
      codexAssistantTrigger.setAttribute("aria-label", label);
      codexAssistantTrigger.setAttribute("title", uiText("询问 Codex", "Ask Codex"));
      codexAssistantTrigger.setAttribute("aria-expanded", String(!!ui.codexAssistantOpen));
      codexAssistantTrigger.classList.toggle("active", !!ui.codexAssistantOpen);
    }
    if (!codexAssistantRoot) return;
    codexAssistantRoot.innerHTML = ui.codexAssistantOpen ? `<div class="codex-floating-backdrop" data-action="global-codex-toggle"></div><aside class="codex-floating-drawer" id="codexAssistantDrawer" role="dialog" aria-modal="true" aria-label="${esc(label)}"><div class="codex-floating-resize-handle" role="separator" tabindex="0" aria-label="${esc(uiText("调整助手面板宽度", "Resize assistant panel"))}" title="${esc(uiText("拖动或使用方向键调整宽度", "Drag or use arrow keys to resize"))}" aria-orientation="vertical" aria-valuemin="200" aria-valuemax="960" aria-valuenow="460"></div><button type="button" class="codex-floating-close" data-action="global-codex-toggle" aria-label="${esc(uiText("关闭助手", "Close assistant"))}">${icon("close")}</button>${project ? renderCodexAssistantPanel(project) : `<section class="codex-assistant-empty"><h2>${uiText("Codex 评估助手", "Codex Assessment Assistant")}</h2><p>${uiText("请先创建 ASPICE 评估项目。", "Create an ASPICE assessment project first.")}</p></section>`}</aside>` : "";
    injectIcons(codexAssistantRoot);
  }

  function renderGlobalAiHarnessHistory() {
    if (!aiHarnessHistoryRoot) return;
    codexHarnessMonitor?.stop();
    codexHarnessMonitor = null;
    const label = uiText("评估运行历史", "Assessment run history");
    const description = uiText(
      "保留阶段状态、过程域映射和证据定位；不记录私有思维链或资料正文。",
      "Stage status, process mapping and evidence locators are retained; private reasoning and source text are not."
    );
    aiHarnessHistoryRoot.innerHTML = `<button type="button" class="af-harness-history-trigger" data-action="toggle-ai-harness-history" aria-label="${esc(label)}" title="${esc(label)}" aria-expanded="${ui.aiHarnessHistoryOpen}">${icon("clock")}</button>${ui.aiHarnessHistoryOpen ? `<div class="codex-floating-backdrop" data-action="toggle-ai-harness-history"></div><aside class="af-harness-history-drawer" role="dialog" aria-label="${esc(label)}"><header class="af-harness-history-head"><div><h2>${esc(label)}</h2><p>${esc(description)}</p></div><button type="button" class="af-harness-history-close" data-action="toggle-ai-harness-history" aria-label="${esc(uiText("关闭运行历史", "Close run history"))}">${icon("close")}</button></header><div class="af-harness-history-body"><div data-ai-harness-history-panel></div></div></aside>` : ""}`;
    injectIcons(aiHarnessHistoryRoot);
    if (!ui.aiHarnessHistoryOpen || !window.AuditFlowAiHarnessUI) return;
    const mount = aiHarnessHistoryRoot.querySelector("[data-ai-harness-history-panel]");
    if (!mount) return;
    const bridgeOrigin = (() => {
      try {
        const parsed = new URL(String(AuditFlowBackend.assistantBaseUrl || ""));
        return parsed.protocol === "http:" && ["127.0.0.1", "localhost", "[::1]", "::1"].includes(parsed.hostname)
          ? parsed.origin
          : "";
      } catch (_) { return ""; }
    })();
    if (!bridgeOrigin) return;
    const project = globalCodexProject();
    const query = new URLSearchParams({ limit: "50", ...(project?.id ? { projectId: project.id } : {}) });
    const localAnswers = project
      ? codexAssistantHistoryFor(project)
        .filter(message => message?.role === "assistant" && message?.runId)
        .slice(-50)
        .map(message => ({ runId: message.runId, content: message.content }))
      : [];
    codexHarnessMonitor = window.AuditFlowAiHarnessUI.mount({
      mount,
      endpoint: `/api/ai/harness/runs?${query}`,
      intervalMs: 5000,
      headers: AuditFlowBackend.authHeaders(),
      credentials: "include",
      localAnswers,
      fetchImpl: (endpoint, options = {}) => fetch(`${bridgeOrigin}${endpoint}`, {
        ...options,
        credentials: "include",
        headers: AuditFlowBackend.authHeaders(options.headers || {})
      })
    });
  }

  function openHelixConfigModal() {
    const bridgeUrl = helixUi.bridgeUrl || HELIX_DEFAULTS.bridgeUrl;
    const apiUrl = helixUi.snapshot?.baseUrl || helixUi.baseUrl || "";
    openModal({
      title: uiText("Helix 配置", "Helix configuration"),
      body: `<section class="helix-config-modal"><p>${uiText("地址来自当前本机 bridge 会话；密码不会写入 AuditFlow 工作区。", "These values come from the local bridge session; passwords are never stored in the AuditFlow workspace.")}</p><label class="form-field full"><span>Bridge URL</span><input readonly value="${esc(bridgeUrl)}"></label><label class="form-field full"><span>Helix REST API URL</span><input readonly value="${esc(apiUrl)}" placeholder="https://host/helix-alm/api/v0"></label></section>`,
      footer: `<button class="btn primary" data-action="close-modal">${uiText("完成", "Done")}</button>`
    });
  }

  function openLatestChange() {
    const entries = [...(db.activity || []), ...visibleStandardProjects().flatMap(project => (project.logs || []).slice(0, 12).map(item => ({ ...item, title: item.action || "Project change", detail: `${project.id} · ${item.comment || ""}` })))].filter(item => item.date).sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 12);
    openModal({ title: uiText("最新变更", "Latest change"), wide: true, body: entries.length ? `<div class="latest-change-list">${entries.map(item => `<article><span class="activity-icon">${icon("rotate")}</span><div><strong>${esc(localizedActivityText(item.title || "Change", "Workspace change"))}</strong><p>${esc(localizedActivityText(item.detail || "", "No change details available"))}</p><small>${formatDate(item.date)}</small></div></article>`).join("")}</div>` : `<div class="empty-mini">${uiText("当前没有可显示的变更。", "No recent changes are available.")}</div>`, footer: `<button class="btn secondary" data-action="close-modal">${uiText("关闭", "Close")}</button>` });
  }

  function renderProjectBrowser() {
    if (!projectBrowserRoot) return;
    if (!ui.projectBrowserOpen) { projectBrowserRoot.replaceChildren(); return; }
    const projects = visibleStandardProjects().filter(project => project.status !== "archived");
    projectBrowserRoot.innerHTML = `<div class="model-browser-backdrop" data-action="toggle-project-browser"></div><aside class="model-browser-panel project-browser-panel" role="dialog" aria-label="${esc(uiText("项目浏览器", "Project browser"))}"><header><strong>${uiText("项目浏览器", "Project browser")}</strong><button type="button" class="model-browser-close" data-action="toggle-project-browser" aria-label="${esc(uiText("关闭项目浏览器", "Close project browser"))}">${icon("close")}</button></header><div class="model-browser-list">${projects.map(project => `<button type="button" class="model-browser-item" data-action="open-project-browser-item" data-project="${esc(project.id)}"><strong>${esc(localizedField(project, "name", project.name))}</strong><small>${esc(project.id)} · ${esc(project.organization || "")}</small><span>${esc(project.status || "Draft")} · ${Number(project.progress || 0)}%</span></button>`).join("") || `<div class="empty-mini">${uiText("当前没有可访问项目。", "No accessible projects are available.")}</div>`}</div></aside>`;
    injectIcons(projectBrowserRoot);
  }

  function renderAccountSettings() {
    const authUser=globalThis.AuditFlowAuth?.user || currentCollaborationUser();
    if (!cloudCollaborationMode()) return `<section class="setting-section"><div class="section-title-row"><div><span class="overline">Local account access</span><h2>${uiText("当前账号", "Current account")}</h2><p>${uiText("本机账号只控制本地可见性；在多人协作设置中登录服务器账号后即可切换到远端项目。", "The local profile controls local visibility; sign in to a server account in Collaboration to access shared projects.")}</p></div>${badge("success",uiText("管理员","Administrator"))}</div><div class="account-identity-card"><div class="account-avatar">${esc(String(authUser?.name || authUser?.email || "AF").slice(0,2).toUpperCase())}</div><div><strong>${esc(authUser?.name || authUser?.email || "AuditFlow user")}</strong><small>${esc(authUser?.email || "local account")}</small></div><div class="row-actions"><button class="btn secondary sm" data-action="switch-account">${icon("refresh")}${uiText("切换账号", "Switch account")}</button><button class="btn danger sm" data-action="logout-account">${icon("close")}${uiText("退出账号", "Sign out")}</button></div></div></section><section class="setting-section"><h2>${uiText("本机权限模型", "Local permission model")}</h2><p>${uiText("本机模式不连接协作服务；每个本机登录账号都是管理员，可编辑可见的全部项目。", "Local mode does not connect to the collaboration service. Every local profile is an administrator and can edit every visible project.")}</p><div class="switch-line"><div><strong>${uiText("项目编辑", "Project editing")}</strong><p>${uiText("项目名称、组织、产品、范围、证据与评估属性均可修改。", "Project name, organisation, product, scope, evidence, and assessment attributes are editable.")}</p></div>${badge("success",uiText("完全可编辑","Fully editable"))}</div></section>`;
    const adminPanel = isAdministrator() && cloudCollaborationMode() ? `<section class="setting-section admin-overview-panel"><div class="section-title-row"><div><span class="overline">Server administration</span><h2>Accounts, projects and permissions</h2><p>Global administrator access to server data. Project owners remain lead assessors; other assessors can submit forms, remarks and traceability only.</p></div><button class="btn secondary sm" data-action="load-admin-overview">${icon("refresh")}Refresh server data</button></div><div id="adminOverviewOutput"><div class="empty-mini">Select Refresh server data to load the current account and project registry.</div></div></section>` : "";
    return `<section class="setting-section"><div class="section-title-row"><div><span class="overline">Account access</span><h2>${uiText("当前账号", "Current account")}</h2><p>${uiText("支持退出当前账号和切换账号；切换后保留本地证据与人工结论。", "Sign out or switch account while keeping local evidence and assessor-owned conclusions.")}</p></div>${badge(isAdministrator()?"success":"info",isAdministrator()?"Administrator":"Assessor")}</div><div class="account-identity-card"><div class="account-avatar">${esc(String(authUser?.name || authUser?.email || "AF").slice(0,2).toUpperCase())}</div><div><strong>${esc(authUser?.name || authUser?.email || "AuditFlow user")}</strong><small>${esc(authUser?.email || "local account")}</small></div><div class="row-actions"><button class="btn secondary sm" data-action="switch-account">${icon("refresh")}${uiText("切换账号", "Switch account")}</button><button class="btn danger sm" data-action="logout-account">${icon("close")}${uiText("退出账号", "Sign out")}</button></div></div></section><section class="setting-section"><h2>${uiText("评估角色与权限", "Assessment roles and permissions")}</h2><p>${uiText("管理员可以在线为项目成员分配角色和过程域；AI 仅提供候选结论，不覆盖人工评分、批准、基线或关闭状态。", "Administrators can assign project roles and process scopes online; AI remains advisory and never overwrites ratings, approvals, baselines or closure states.")}</p>${[["Lead Assessor","评分 PA、关闭评估、管理参与者和定稿"],["Assessor","创建记录、评分 BP/GP、填写意见与追溯备注"],["Viewer","只读访问评估数据"]].map(x=>`<div class="switch-line"><div><strong>${x[0]}</strong><p>${x[1]}</p></div>${badge(x[0]==="Lead Assessor"?"success":"neutral",x[0]==="Lead Assessor"?uiText("可关闭","Closure authority"):uiText("可分配","Assignable"))}</div>`).join("")}</section><section class="setting-section"><div class="section-title-row"><div><h2>${uiText("在线项目权限", "Online project permissions")}</h2><p>${uiText("项目创建者是 Lead Assessor，只有他或总管理员可以上传文件、改配置和确认证据。", "The project creator is the Lead Assessor; only the lead or global administrator can upload files, change configuration, or confirm evidence.")}</p></div><button class="btn primary sm" data-action="open-collaboration-settings">${icon("users")}${uiText("管理项目权限", "Manage project access")}</button></div></section>`;
  }

  function adminAccountId(account = {}) {
    return String(account.userId || account.id || "").trim();
  }

  function adminAccountName(account = {}) {
    return String(account.displayName || account.name || account.email || adminAccountId(account) || "AuditFlow user");
  }

  function adminProjectId(project = {}) {
    return String(project.projectId || project.id || "").trim();
  }

  function adminProjectDirectory() {
    const remoteProjects = Array.isArray(ui.adminDirectory?.projects) ? ui.adminDirectory.projects : [];
    const localProjects = [...(db.standardProjects || []), ...(db.customAudits || [])];
    return remoteProjects.map(remote => {
      const cloudId = adminProjectId(remote);
      const local = localProjects.find(project => cloudProjectKey(project) === cloudId || project.collaboration?.cloudProjectId === cloudId || project.id === remote.snapshot?.id);
      return {
        remote,
        cloudId,
        local,
        name: String(remote.name || remote.snapshot?.name || local?.name || cloudId || "Shared project"),
        revision: Number(remote.revision ?? local?.collaboration?.remoteRevision ?? 0),
        members: Array.isArray(remote.members) ? remote.members : []
      };
    }).filter(project => project.cloudId);
  }

  function adminScopeOptions(project, selectedScopes = []) {
    const selected = new Set(selectedScopes || []);
    const configured = project?.local?.processes || project?.remote?.snapshot?.processes || [];
    const options = [["*", "All configured processes"], ...configured.map(process => [String(process), String(process)])];
    return options.map(item => '<option value="' + esc(item[0]) + '"' + (selected.has(item[0]) ? " selected" : "") + '>' + esc(item[1]) + '</option>').join("");
  }

  function adminDefaultPermissions(role, permissions = {}) {
    const editable = role !== "Viewer";
    const result = {
      view: permissions.view !== false,
      use: permissions.use ?? editable,
      forms: permissions.forms ?? editable,
      remarks: permissions.remarks ?? editable,
      traceability: permissions.traceability ?? editable
    };
    if (role === "Lead Assessor") return { view: true, use: true, forms: true, remarks: true, traceability: true };
    if (role === "Viewer") return { view: result.view, use: false, forms: false, remarks: false, traceability: false };
    if (!result.view) return { view: false, use: false, forms: false, remarks: false, traceability: false };
    if (!result.use) return { ...result, forms: false, remarks: false, traceability: false };
    return result;
  }

  function syncAdminAccessRow(row) {
    if (!row) return;
    const role = String(row.querySelector("[data-admin-access-role]")?.value || "Viewer");
    const toggles = Object.fromEntries(["view", "use", "forms", "remarks", "traceability"].map(key => [key, row.querySelector(`[data-admin-access-permission="${key}"]`)]));
    const scope = row.querySelector("[data-admin-access-scopes]");
    if (role === "Lead Assessor") {
      Object.values(toggles).forEach(toggle => { if (toggle) { toggle.checked = true; toggle.disabled = true; } });
      if (scope) { [...scope.options].forEach(option => { option.selected = option.value === "*"; }); scope.disabled = true; }
      return;
    }
    if (scope) scope.disabled = role === "Viewer";
    if (role === "Viewer") {
      if (toggles.view) { toggles.view.checked = true; toggles.view.disabled = true; }
      ["use", "forms", "remarks", "traceability"].forEach(key => { if (toggles[key]) { toggles[key].checked = false; toggles[key].disabled = true; } });
      return;
    }
    if (toggles.view) toggles.view.disabled = false;
    if (!toggles.view?.checked) {
      ["use", "forms", "remarks", "traceability"].forEach(key => { if (toggles[key]) { toggles[key].checked = false; toggles[key].disabled = true; } });
      return;
    }
    if (toggles.use) toggles.use.disabled = false;
    const editable = !!toggles.use?.checked;
    ["forms", "remarks", "traceability"].forEach(key => { if (toggles[key]) { toggles[key].disabled = !editable; if (!editable) toggles[key].checked = false; } });
  }

  const ADMIN_PERMISSION_DEFINITIONS = Object.freeze([
    { group: "Global permissions", label: "Account directory", description: "View and manage registered AuditFlow accounts.", id: "ADMIN_DIRECTORY", roles: ["Administrator"] },
    { group: "Project permissions", label: "Project read", description: "Open the project snapshot and read its evidence index.", id: "PROJECT_VIEW", key: "view", roles: ["Administrator", "Lead Assessor", "Assessor", "Viewer"] },
    { group: "Project permissions", label: "Project use", description: "Use the assessment workspace within the assigned process scope.", id: "PROJECT_USE", key: "use", roles: ["Administrator", "Lead Assessor", "Assessor"] },
    { group: "Assessment permissions", label: "Record forms", description: "Create and update draft assessor records and forms.", id: "PROJECT_FORMS", key: "forms", roles: ["Administrator", "Lead Assessor", "Assessor"] },
    { group: "Assessment permissions", label: "Review remarks", description: "Edit candidate rationale, review notes and finding text.", id: "PROJECT_REMARKS", key: "remarks", roles: ["Administrator", "Lead Assessor", "Assessor"] },
    { group: "Traceability permissions", label: "Evidence traceability", description: "Create or update unconfirmed evidence relationships.", id: "PROJECT_TRACEABILITY", key: "traceability", roles: ["Administrator", "Lead Assessor", "Assessor"] },
    { group: "Scope permissions", label: "Process scope", description: "Limit project use to selected formal ASPICE processes.", id: "PROJECT_PROCESS_SCOPE", roles: ["Administrator", "Lead Assessor", "Assessor", "Viewer"] }
  ]);

  function adminPermissionCatalogMarkup() {
    const roleName = role => ({Administrator: uiText("管理员", "Administrator"), "Lead Assessor": uiText("主审核员", "Lead Assessor"), Assessor: uiText("审核员", "Assessor"), Viewer: uiText("只读成员", "Viewer")}[role] || role);
    const rows = ADMIN_PERMISSION_DEFINITIONS.map(permission => `<tr><td><strong>${esc(uiText(permission.group === "Global permissions" ? "全局权限" : permission.group === "Project permissions" ? "项目权限" : permission.group === "Assessment permissions" ? "评估权限" : permission.group === "Traceability permissions" ? "追溯权限" : "范围权限", permission.group))}</strong></td><td><strong>${esc(permission.label)}</strong><small>${esc(uiText(permission.description, permission.description))}</small></td><td><code>${esc(permission.id)}</code></td><td>${permission.roles.map(role => `<span class="admin-role-chip">${esc(roleName(role))}</span>`).join(" ")}</td></tr>`).join("");
    return `<section class="setting-section admin-permission-catalog"><div class="section-title-row"><div><span class="overline">${uiText("Trace 风格权限方案", "Trace-style permission scheme")}</span><h2>${uiText("权限目录", "Permission catalog")}</h2><p>${uiText("每个访问决策都映射到稳定的权限 ID。角色预设提供起点，项目范围和明确的能力开关始终对管理员可见。", "Every access decision maps to a stable permission ID. Role presets provide a starting point; project scope and explicit capability switches remain visible to the administrator.")}</p></div><span class="badge info">${uiText("架构", "Schema")} v${Number(ui.adminDirectory?.permissionSchemaVersion || 1)}</span></div><div class="live-table-wrap"><table class="data-table"><thead><tr><th>${uiText("权限组", "Permission group")}</th><th>${uiText("权限说明", "Permission description")}</th><th>${uiText("权限 ID", "Permission ID")}</th><th>${uiText("默认角色", "Default roles")}</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
  }

  async function refreshAdminWorkspace({ quiet = false } = {}) {
    if (!cloudCollaborationMode() || !isAdministrator()) return null;
    configureCloudClient();
    const responses = await Promise.all([
      AuditFlowBackend.adminAccounts(),
      AuditFlowBackend.adminOverview()
    ]);
    const directory = responses[0] || {};
    const overview = responses[1] || {};
    const accounts = Array.isArray(directory.accounts) ? directory.accounts : (Array.isArray(overview.accounts) ? overview.accounts : []);
    ui.adminDirectory = { ...overview, accounts };
    mergeCollaborationDirectory(accounts);
    const projects = adminProjectDirectory();
    if (!projects.some(project => project.cloudId === ui.adminProjectId)) ui.adminProjectId = projects[0]?.cloudId || "";
    if (!quiet) toast("Administration refreshed", "Registered accounts and project access rules are current.", "success");
    return ui.adminDirectory;
  }

  function renderAdminOverview(data) {
    ui.adminDirectory = { ...(ui.adminDirectory || {}), ...(data || {}) };
    if (Array.isArray(data?.accounts)) mergeCollaborationDirectory(data.accounts);
    if (ui.settingsTab === "admin") render();
  }

  function renderAdminSettings() {
    if (!cloudCollaborationMode() || !isAdministrator()) {
      return '<section class="setting-section"><h2>Administrator access required</h2><p>Only the configured AuditFlow administrator can manage account records and project access.</p></section>';
    }

    const directory = ui.adminDirectory || {};
    const accounts = Array.isArray(directory.accounts) ? directory.accounts : [];
    const projects = adminProjectDirectory();
    const selectedProject = projects.find(project => project.cloudId === ui.adminProjectId) || projects[0] || null;
    const projectOptions = projects.map(project => '<option value="' + esc(project.cloudId) + '"' + (selectedProject?.cloudId === project.cloudId ? " selected" : "") + '>' + esc(project.name) + ' · r' + Number(project.revision || 0) + '</option>').join("");
    const accountRows = accounts.map(account => {
      const userId = adminAccountId(account);
      const protectedAccount = account.isAdmin === true;
      const disabled = account.disabled === true;
      return '<tr data-admin-account-row="' + esc(userId) + '">' +
        '<td><input class="admin-directory-input" type="email" data-admin-account-email value="' + esc(account.email || "") + '" maxlength="254"' + (protectedAccount ? " readonly" : "") + ' aria-label="Email for ' + esc(adminAccountName(account)) + '"><br><small>' + esc(userId) + '</small></td>' +
        '<td><input class="admin-directory-input" type="text" data-admin-account-name value="' + esc(adminAccountName(account)) + '" maxlength="160" aria-label="Display name for ' + esc(account.email || userId) + '"></td>' +
        '<td><label class="admin-status-toggle"><input type="checkbox" data-admin-account-disabled' + (disabled ? " checked" : "") + (protectedAccount ? " disabled" : "") + '><span>' + (disabled ? "Disabled" : "Active") + '</span></label></td>' +
        '<td>' + badge(protectedAccount ? "info" : (disabled ? "warn" : "success"), protectedAccount ? "Administrator" : (disabled ? "Disabled" : "Active")) + '</td>' +
        '<td><div class="row-actions"><button type="button" class="btn secondary sm" data-action="admin-save-account" data-user="' + esc(userId) + '">Save</button><button type="button" class="btn ghost sm" data-action="admin-open-reset-password" data-user="' + esc(userId) + '" data-name="' + esc(adminAccountName(account)) + '">Reset password</button></div></td>' +
      '</tr>';
    }).join("") || '<tr><td colspan="5"><div class="empty-mini">Refresh the directory to load registered accounts.</div></td></tr>';

    let accessPanel = '<div class="empty-mini">Refresh the administrator workspace to load project access rules.</div>';
    if (selectedProject) {
      const memberByUser = new Map(selectedProject.members.map(member => [String(member.userId || member.id || ""), member]));
      const accessRows = accounts.map(account => {
        const userId = adminAccountId(account);
        const member = memberByUser.get(userId);
        const role = member?.role || "Viewer";
        const permissions = adminDefaultPermissions(role, member?.permissions || {});
        const scopes = member?.processScopes || (role === "Lead Assessor" ? ["*"] : []);
        const disabled = account.disabled === true;
        return '<tr data-admin-access-row="' + esc(userId) + '">' +
          '<td><strong>' + esc(adminAccountName(account)) + '</strong><br><small>' + esc(account.email || userId) + '</small></td>' +
          '<td><select data-admin-access-role aria-label="Project role"><option value="Lead Assessor"' + (role === "Lead Assessor" ? " selected" : "") + '>Lead Assessor</option><option value="Assessor"' + (role === "Assessor" ? " selected" : "") + '>Assessor</option><option value="Viewer"' + (role === "Viewer" ? " selected" : "") + '>Viewer</option></select></td>' +
          '<td><select multiple size="2" data-admin-access-scopes aria-label="Process scopes">' + adminScopeOptions(selectedProject, scopes) + '</select></td>' +
          '<td><div class="admin-permission-grid">' +
            '<label title="PROJECT_VIEW"><input type="checkbox" data-admin-access-permission="view"' + (permissions.view ? " checked" : "") + '>View</label>' +
            '<label title="PROJECT_USE"><input type="checkbox" data-admin-access-permission="use"' + (permissions.use ? " checked" : "") + '>Use</label>' +
            '<label title="PROJECT_FORMS"><input type="checkbox" data-admin-access-permission="forms"' + (permissions.forms ? " checked" : "") + '>Forms</label>' +
            '<label title="PROJECT_REMARKS"><input type="checkbox" data-admin-access-permission="remarks"' + (permissions.remarks ? " checked" : "") + '>Remarks</label>' +
            '<label title="PROJECT_TRACEABILITY"><input type="checkbox" data-admin-access-permission="traceability"' + (permissions.traceability ? " checked" : "") + '>Traceability</label>' +
          '</div></td>' +
          '<td><div class="row-actions"><button type="button" class="btn secondary sm" data-action="admin-save-project-access" data-project="' + esc(selectedProject.cloudId) + '" data-user="' + esc(userId) + '" data-revision="' + Number(selectedProject.revision || 0) + '"' + (disabled ? " disabled" : "") + '>Save access</button>' +
          (member ? '<button type="button" class="btn ghost sm" data-action="admin-remove-project-access" data-project="' + esc(selectedProject.cloudId) + '" data-user="' + esc(userId) + '" data-revision="' + Number(selectedProject.revision || 0) + '">Remove</button>' : '') +
          '</div></td>' +
        '</tr>';
      }).join("") || '<tr><td colspan="5"><div class="empty-mini">Create an account before assigning project access.</div></td></tr>';
      const memberCount = selectedProject.members.length;
      accessPanel = '<div class="admin-project-access"><div class="admin-project-context"><div><span class="overline">Selected project</span><strong>' + esc(selectedProject.name) + '</strong><small>' + esc(selectedProject.cloudId) + ' · revision r' + Number(selectedProject.revision || 0) + '</small></div><div><span>Members</span><strong>' + memberCount + '</strong></div><div><span>Evidence</span><strong>' + Number(selectedProject.remote?.evidenceCount || 0) + '</strong></div><div><span>Assessments</span><strong>' + Number(selectedProject.remote?.assessmentCount || 0) + '</strong></div></div><div class="form-grid"><div class="form-field full"><label>Project</label><select data-admin-project-select>' + projectOptions + '</select><small>Every access change is sent with the current server revision to prevent one administrator from overwriting another.</small></div></div><div class="live-table-wrap"><table class="data-table admin-access-table"><thead><tr><th>Registered member</th><th>Role</th><th>Process scope</th><th>Capabilities</th><th></th></tr></thead><tbody>' + accessRows + '</tbody></table></div></div>';
    }

    return '<section class="setting-section admin-directory-panel">' +
      '<div class="section-title-row"><div><span class="overline">Account, AI and local parsing settings</span><h2>Administration</h2><p>Manage registered accounts and project access from the shared service. Changes to project access use a revision check and take effect on the next collaboration refresh.</p></div><button type="button" class="btn secondary sm" data-action="refresh-admin-workspace">' + icon("refresh") + 'Refresh</button></div>' +
      '<div class="admin-summary-grid"><div><span>Registered accounts</span><strong>' + accounts.length + '</strong></div><div><span>Shared projects</span><strong>' + projects.length + '</strong></div><div><span>Feedback records</span><strong>' + Number(directory.feedbackCount || 0) + '</strong></div><div><span>Permission schema</span><strong>v' + Number(directory.permissionSchemaVersion || 1) + '</strong></div><div class="admin-summary-wide"><span>Persistence boundary</span><strong>Accounts, memberships, process scopes, capability JSON, project snapshots and revision events</strong><small>Original evidence attachment binaries remain in the authenticated FileAnalyst storage boundary.</small></div></div>' +
    '</section>' +
    '<section class="setting-section admin-runtime-panel"><div class="section-title-row"><div><span class="overline">Runtime administration</span><h2>Port and database status</h2><p>Runtime values are read-only in the client. Change listening ports and database credentials through the Windows deployment environment or service manager.</p></div><span class="badge info">Server-side only</span></div><div class="admin-summary-grid"><div><span>Desktop backend</span><strong>' + esc(window.AuditFlowDesktopServices?.backendVersion || APP_VERSION) + '</strong><small>' + (window.AuditFlowDesktopServices?.backendHealthy ? 'Healthy' : 'Unavailable') + '</small></div><div><span>Database provider</span><strong>' + esc(directory.database?.provider || 'server-managed') + '</strong><small>' + (directory.database?.configured ? 'Configured' : 'Not reported') + '</small></div><div><span>Sync interval</span><strong>' + Number(directory.pollIntervalMs || 1000) + ' ms</strong><small>Revision polling</small></div><div><span>Security boundary</span><strong>Credentials protected</strong><small>Passwords are never rendered or stored here.</small></div></div><div class="page-actions"><button type="button" class="btn secondary" data-action="refresh-admin-workspace">Refresh runtime status</button></div></section>' +
    adminPermissionCatalogMarkup() +
    '<section class="setting-section"><div class="section-title-row"><div><h2>Create account</h2><p>Create a registered AuditFlow account. The temporary password is sent only to the service and is never displayed or stored by this page.</p></div></div>' +
      '<form id="adminCreateAccountForm" class="form-grid" autocomplete="off"><div class="form-field"><label>Email *</label><input name="email" type="email" required maxlength="254" autocomplete="off"></div><div class="form-field"><label>Display name *</label><input name="displayName" required maxlength="160"></div><div class="form-field"><label>Temporary password *</label><input name="password" type="password" required minlength="10" autocomplete="new-password"></div><div class="form-field admin-create-action"><button type="button" class="btn primary" data-action="admin-create-account">' + icon("plus") + 'Create account</button></div></form>' +
    '</section>' +
    '<section class="setting-section"><div class="section-title-row"><div><h2>Registered accounts</h2><p>Update display names, enable or disable access, and reset a password when needed. Configured administrator identities remain protected by the server.</p></div></div><div class="live-table-wrap"><table class="data-table"><thead><tr><th>Account</th><th>Display name</th><th>Sign-in</th><th>Status</th><th></th></tr></thead><tbody>' + accountRows + '</tbody></table></div></section>' +
    '<section class="setting-section"><div class="section-title-row"><div><h2>Project access</h2><p>Assign a registered member to a project, choose the project role, limit the formal process scope, and grant the capabilities needed for the assessment work.</p></div></div>' + accessPanel + '</section>';
  }
  function renderHelixSettings() {
    const s = db.settings || {};
    if (currentLanguage() !== "en") return null;
    const fieldGroupLabels = { identity: "Identity", content: "Object content", state: "Status", ownership: "Ownership and approval", control: "Version and baseline", trace: "Upstream and downstream traceability", impact: "Impact and closure" };
    const fieldGroups = HELIX_FIELD_GROUPS.map(([key, , terms]) => { const englishTerms = terms.filter(term => !/[\u3400-\u9fff]/.test(term)); return `<label><input type="checkbox" checked disabled> ${esc(fieldGroupLabels[key] || key)} · ${esc(englishTerms.slice(0, 4).join(" / "))}</label>`; }).join("");
    const rows = [["Stable locators", "Keep Sheet/Slide/Page, table, and row references for every citation."], ["Target-process directness", "Only target-process fields and object content can be classified as direct."], ["Related-process isolation", "Upstream, downstream, MAN.3, and SUP data remain corroborating by default."], ["Assessor confirmation", "The assessor samples status, relationship type, version, and closure semantics."]];
    return `<section class="setting-section"><h2>Helix table parsing</h2><p>AuditFlow reads Helix XLSX/XLSM, DOCX, PPTX, and PDF exports locally in the browser. No external server is contacted.</p><form id="helixConfigForm"><div class="switch-line"><div><strong>Auto-detect Helix exports</strong><p>Identify object tables from ID, status, ownership, version/baseline, traceability, and closure fields.</p></div><label class="switch"><input name="helixAutoDetect" type="checkbox" ${s.helixAutoDetect ? "checked" : ""}><i></i></label></div><div class="switch-line"><div><strong>Require unique identity fields</strong><p>Avoid treating ordinary summary tables as auditable Helix object tables.</p></div><label class="switch"><input name="helixRequireIdentity" type="checkbox" ${s.helixRequireIdentity ? "checked" : ""}><i></i></label></div><div class="form-grid" style="margin-top:17px"><div class="form-field"><label>Maximum rows retained per table</label><input name="helixMaxRows" type="number" min="20" max="200" value="${Number(s.helixMaxRows || 60)}"><small>Full row counts remain in statistics; the browser stores a bounded preview to control project size.</small></div><div class="form-field full"><label>Built-in field groups</label><div class="check-grid">${fieldGroups}</div></div></div><div class="page-actions" style="margin-top:16px"><button type="button" class="btn secondary" data-action="test-helix-parser">Check parser</button><button class="btn primary" data-action="save-helix-settings">Save settings</button></div></form></section><section class="setting-section"><h2>Evidence-use guardrails</h2><p>Successfully reading a table does not mean that a BP or GP is achieved.</p>${rows.map(item => `<div class="switch-line"><div><strong>${item[0]}</strong><p>${item[1]}</p></div>${badge("success", "Required")}</div>`).join("")}</section>`;
  }

  function renderPrivacySettings() {
    const s = db.settings || {};
    if (currentLanguage() !== "en") return null;
    return `<section class="setting-section"><h2>Local data policy</h2><p>Project metadata, evidence indexes, ratings, and report versions are stored in browser local storage by default.</p><div class="switch-line"><div><strong>Retain evidence text</strong><p>Keep parsed text for re-assessment and report generation; sensitive projects can retain metadata only.</p></div><label class="switch"><input type="checkbox" data-setting="retainEvidenceText" ${s.retainEvidenceText ? "checked" : ""}><i></i></label></div><div class="switch-line"><div><strong>Minimise model transfer</strong><p>External AI receives only the necessary excerpts for the current assessment item.</p></div>${badge("success", "Enabled")}</div><div class="switch-line"><div><strong>Export workspace backup</strong><p>Save current projects, schemes, ratings, and settings as JSON.</p></div><button class="btn secondary sm" data-action="export-workspace">${icon("download")}Export</button></div><div class="switch-line"><div><strong>Restore demo data</strong><p>Clear local browser edits and restore the initial workspace.</p></div><button class="btn danger sm" data-action="reset-workspace">Restore demo</button></div></section>`;
  }

  function settingsContent() {
    if (ui.settingsTab === "help") return renderHelpCenter();
    if (ui.settingsTab === "feedback") return renderFeedback();
    if (ui.settingsTab === "recycle-bin") return renderRecycleBinSettings();
    const s = db.settings;
    if (ui.settingsTab === "codex") return renderCodexSettings();
    if (ui.settingsTab === "monitor") return renderConnectionProgressSettings();
    if (ui.settingsTab === "ai") return renderAiSettings();
    if (ui.settingsTab === "mcp") return renderMcpSettings();
    if (ui.settingsTab === "collaboration") return renderCollaborationSettings();
    if (ui.settingsTab === "admin") return renderAdminSettings();
    if (ui.settingsTab === "classification") return renderClassificationSettings();
    if (ui.settingsTab === "account") return renderAccountSettings();
    if (ui.settingsTab === "helix") return renderHelixSettings() || `<section class="setting-section"><h2>Helix 表格解析</h2><p>AuditFlow 在浏览器本地读取 Helix 导出的 XLSX/XLSM、DOCX、PPTX 或 PDF 表格，不连接外部服务器。</p><form id="helixConfigForm"><div class="switch-line"><div><strong>自动识别 Helix 导出</strong><p>根据 ID、状态、责任、版本/基线、追溯和闭环字段识别对象表。</p></div><label class="switch"><input name="helixAutoDetect" type="checkbox" ${s.helixAutoDetect?"checked":""}><i></i></label></div><div class="switch-line"><div><strong>要求唯一标识字段</strong><p>避免把普通汇总表误判为可审计的 Helix 对象表。</p></div><label class="switch"><input name="helixRequireIdentity" type="checkbox" ${s.helixRequireIdentity?"checked":""}><i></i></label></div><div class="form-grid" style="margin-top:17px"><div class="form-field"><label>每个表格保留的最大行数</label><input name="helixMaxRows" type="number" min="20" max="200" value="${Number(s.helixMaxRows||60)}"><small>完整行数会保留统计，浏览器只保存有限预览以控制项目包大小。</small></div><div class="form-field full"><label>内置字段组</label><div class="check-grid">${HELIX_FIELD_GROUPS.map(([,label,terms])=>`<label><input type="checkbox" checked disabled> ${esc(label)} · ${esc(terms.slice(0,4).join(" / "))}</label>`).join("")}</div></div></div><div class="page-actions" style="margin-top:16px"><button type="button" class="btn secondary" data-action="test-helix-parser">检查解析器</button><button class="btn primary" data-action="save-helix-settings">保存设置</button></div></form></section><section class="setting-section"><h2>证据使用护栏</h2><p>表格被成功读取不等于 BP/GP 已满足。</p>${[["稳定定位","每条引用保留 Sheet/Slide/Page、表格和行号"],["目标过程直接性","只有目标过程字段和对象内容可以作为 direct"],["关联过程隔离","上下游、MAN.3 与 SUP 数据默认只作 corroborating"],["人工最终确认","状态、关系类型、版本和关闭语义由评估师抽样核实"]].map(item=>`<div class="switch-line"><div><strong>${item[0]}</strong><p>${item[1]}</p></div>${badge("success","强制")}</div>`).join("")}</section>`;
    if (ui.settingsTab === "privacy") return renderPrivacySettings() || `<section class="setting-section"><h2>本地数据策略</h2><p>默认所有项目元数据、证据索引、评分和报告版本保存在浏览器 localStorage。</p><div class="switch-line"><div><strong>保留证据文本</strong><p>便于重新评估和生成报告；敏感项目可关闭并只保留文件元数据。</p></div><label class="switch"><input type="checkbox" data-setting="retainEvidenceText" ${s.retainEvidenceText?"checked":""}><i></i></label></div><div class="switch-line"><div><strong>最小化模型传输</strong><p>外部 AI 仅接收当前审核项相关的必要片段。</p></div>${badge("success","已启用")}</div><div class="switch-line"><div><strong>导出工作区备份</strong><p>将当前项目、方案、评分与设置保存为 JSON。</p></div><button class="btn secondary sm" data-action="export-workspace">${icon("download")}导出</button></div><div class="switch-line"><div><strong>恢复演示数据</strong><p>清除当前浏览器中的所有改动并恢复初始状态。</p></div><button class="btn danger sm" data-action="reset-workspace">恢复演示</button></div></section>`;
    return `<section class="setting-section"><h2>本地数据策略</h2><p>默认所有项目元数据、证据索引、评分和报告版本保存在浏览器 localStorage。</p><div class="switch-line"><div><strong>保留证据文本</strong><p>便于重新评估和生成报告；敏感项目可关闭并只保留文件元数据。</p></div><label class="switch"><input type="checkbox" data-setting="retainEvidenceText" ${s.retainEvidenceText?"checked":""}><i></i></label></div><div class="switch-line"><div><strong>最小化模型传输</strong><p>外部 AI 仅接收当前审核项相关的必要片段。</p></div>${badge("success","已启用")}</div><div class="switch-line"><div><strong>导出工作区备份</strong><p>将当前项目、方案、评分与设置保存为 JSON。</p></div><button class="btn secondary sm" data-action="export-workspace">${icon("download")}导出</button></div><div class="switch-line"><div><strong>恢复演示数据</strong><p>清除当前浏览器中的所有改动并恢复初始状态。</p></div><button class="btn danger sm" data-action="reset-workspace">恢复演示</button></div></section>`;
  }

  function renderClassificationSettings() {
    const rules = db.settings.documentClassificationRules || [];
    if (currentLanguage() === "en") {
      const processOptions = [`<option value="">Candidate only; do not force a process</option>`, ...PROCESS_CATALOG.map(process => `<option value="${esc(process.id)}">${esc(process.id)} · ${esc(process.en)}</option>`)].join("");
      const descriptions = { "assessment-record": "Assessment findings, issue lists, action plans, and assessor records; they show that an issue exists but do not prove process implementation.", requirements: "System, software, and hardware requirements and specifications.", "process-governance": "Project plans, policies, procedures, work instructions, baselines, and governance files.", test: "Test specifications, cases, execution results, defects, and verification reports.", traceability: "Requirements-design-test, issue-change-baseline, and other traceability matrices or tool exports." };
      return `<section class="setting-section classification-settings"><header><div><span class="overline">Document taxonomy</span><h2>Item classification rules</h2><p>Use keywords to suggest five document classes, four item types, and ASPICE process candidates. Rules remain suggestions and can be amended by the assessor.</p></div><span class="badge info">${rules.length} custom rules</span></header><form id="classificationRuleForm" class="form-grid"><div class="form-field"><label>Keyword</label><input name="keyword" required placeholder="Example: test case, baseline, action plan"></div><div class="form-field"><label>Document class</label><select name="documentClass">${documentClassOptions("requirements")}</select></div><div class="form-field"><label>Item type</label><select name="itemType">${documentClassificationOptions("information")}</select></div><div class="form-field"><label>ASPICE process candidate</label><select name="process">${processOptions}</select></div><div class="form-field full"><label>Description</label><input name="description" placeholder="Describe when this keyword applies"></div><div class="page-actions full"><button type="button" class="btn primary" data-action="save-classification-rule">${icon("plus")}Add rule</button></div></form><div class="classification-rule-list">${rules.map(rule => `<article><div><strong>${esc(rule.keyword)}</strong><span class="document-class-badge ${esc(rule.documentClass || "requirements")}">${esc(DOCUMENT_CLASSES.find(item => item[0] === (rule.documentClass || "requirements"))?.[2] || "Requirements")}</span><span class="type-chip ${esc(rule.itemType)}">${esc(rule.itemType)}</span>${rule.process ? `<span class="code-tag">${esc(rule.process)}</span>` : ""}<small>${esc(rule.description || "")}</small></div><button class="action-icon danger" data-action="delete-classification-rule" data-id="${esc(rule.id)}" title="Delete rule" aria-label="Delete rule">${icon("trash")}</button></article>`).join("") || `<div class="empty-mini">No custom keyword rules yet. The default document and item rules remain active.</div>`}</div></section><section class="setting-section"><h2>Document classes</h2>${DOCUMENT_CLASSES.map(([value, , english]) => `<div class="switch-line"><div><strong>${english}</strong><p>${esc(descriptions[value] || "")}</p></div><span class="document-class-badge ${value}">${value}</span></div>`).join("")}</section>`;
    }
    const processOptions=[`<option value="">仅作为候选，不强制过程域</option>`,...PROCESS_CATALOG.map(process=>`<option value="${esc(process.id)}">${esc(process.id)} · ${esc(process.zh)}</option>`)].join("");
    const descriptions={"assessment-record":"评审发现、问题收集、整改计划和评估记录；只证明发现存在，不自动证明过程实施。",requirements:"系统/软件/硬件需求与规格；用于对应 SYS.1/SYS.2/SWE.1/HWE.1 等工程过程。","process-governance":"项目计划、策略、流程、WI、基线和治理类纲领文件。",test:"测试规范、用例、执行结果、缺陷与验证报告。",traceability:"需求—设计—测试、问题—变更—基线等追溯矩阵和工具导出表。"};
    return `<section class="setting-section classification-settings"><header><div><span class="overline">Document taxonomy</span><h2>条目分类规则</h2><p>按关键词同时给出五类文件、四类 item 和 ASPICE 过程候选。规则只生成候选，评估师仍可逐条改定。</p></div><span class="badge info">${rules.length} 条自定义规则</span></header><form id="classificationRuleForm" class="form-grid"><div class="form-field"><label>关键词</label><input name="keyword" required placeholder="例如：测试用例、基线、Action Plan"></div><div class="form-field"><label>文件类别</label><select name="documentClass">${documentClassOptions("requirements")}</select></div><div class="form-field"><label>Item 类型</label><select name="itemType">${documentClassificationOptions("information")}</select></div><div class="form-field"><label>ASPICE 过程候选</label><select name="process">${processOptions}</select></div><div class="form-field full"><label>说明</label><input name="description" placeholder="说明该关键词适用的判断范围"></div><div class="page-actions full"><button type="button" class="btn primary" data-action="save-classification-rule">${icon("plus")}添加规则</button></div></form><div class="classification-rule-list">${rules.map(rule => `<article><div><strong>${esc(rule.keyword)}</strong><span class="document-class-badge ${esc(rule.documentClass||"requirements")}">${esc(DOCUMENT_CLASSES.find(item=>item[0]===(rule.documentClass||"requirements"))?.[1]||"需求文件")}</span><span class="type-chip ${esc(rule.itemType)}">${esc(rule.itemType)}</span>${rule.process?`<span class="code-tag">${esc(rule.process)}</span>`:""}<small>${esc(rule.description || "")}</small></div><button class="action-icon danger" data-action="delete-classification-rule" data-id="${esc(rule.id)}" title="删除规则" aria-label="删除规则">${icon("trash")}</button></article>`).join("") || `<div class="empty-mini">尚未添加自定义关键词规则。默认五类文件和四类 item 规则仍然生效。</div>`}</div></section><section class="setting-section"><h2>五类文件定义</h2>${DOCUMENT_CLASSES.map(([value,label,english]) => `<div class="switch-line"><div><strong>${label} · ${english}</strong><p>${esc(descriptions[value]||"")}</p></div><span class="document-class-badge ${value}">${value}</span></div>`).join("")}</section>`;
  }

  function reportRatingClass(rating) { return ["F","L+","L"].includes(rating)?"rating-f":["L-","P+"].includes(rating)?"rating-l":["P","P-"].includes(rating)?"rating-p":"rating-n"; }
  function reportRatingMarkup(rating, withScore = true) { return `<span class="report-rating ${reportRatingClass(rating)}">${esc(rating)}${withScore?` · ${RATING_SCORE[rating]||0}`:""}</span>`; }
  function reportSheet(project, label, body, className = "") { return `<section class="report-sheet ${className}" data-report-sheet="${esc(label)}"><div class="report-running-head"><strong>Process Evaluation · Explanations &amp; Findings</strong><span>ID.-No.: ${esc(project.reportNo)}</span></div>${body}<div class="report-running-foot">© ${new Date().getFullYear()} AuditFlow AI v${APP_VERSION} · ${esc(label)} <span>Codex candidate + assessor review</span></div></section>`; }
  function processReportName(processId) { const proc=PROCESS_CATALOG.find(p=>p.id===processId);return proc?`${proc.id} ${currentLanguage()==="en"?proc.en:proc.zh}`:processId; }
  function isTrainingDeckProvenance(value) {
    return /(?:\.(?:pptx?|potx?|ppsx?)(?:$|[\s·/]))|\bpowerpoint\b|\bppt\b|\bslide(?:s)?\b|\bpage(?:s)?\b|幻灯片|课件|training[\s_-]*deck/i.test(String(value || ""));
  }
  function reportSafeEvidenceSource(value, fallback = "Assessor-confirmed evidence / 受控评估输入") {
    const source = String(value || "").replace(/\s+/g, " ").trim();
    return source && !isTrainingDeckProvenance(source) ? source : fallback;
  }
  function reportSafeEvidenceLocator(value, fallback = "Evidence locator / 证据定位") {
    const locator = String(value || "").replace(/\s+/g, " ").trim();
    return locator && !isTrainingDeckProvenance(locator) ? locator : fallback;
  }
  function reportSafeEvidenceExcerpt(value, fallback = "Controlled evidence excerpt / 受控证据摘录") {
    const excerpt = String(value || "").replace(/\s+/g, " ").trim();
    return excerpt && !isTrainingDeckProvenance(excerpt) ? excerpt : fallback;
  }
  function reportSafeImportedSource(value, fallback = "Controlled assessment input / 受控评估输入") {
    return reportSafeEvidenceSource(value, fallback);
  }
  function reportSafeNarrative(value, fallback = "待评估师确认") {
    const narrative = String(value || "").replace(/\s+/g, " ").trim();
    return narrative && !isTrainingDeckProvenance(narrative) ? narrative : fallback;
  }
  function hasReportableProcessMaterial(project, processId) {
    return reportAssessments(project, processId).length > 0;
  }
  function capabilityChartMarkup(project) {
    const processes = project.processes.filter(processId => hasReportableProcessMaterial(project, processId));
    if (!processes.length) return `<p class="report-empty-state">No assessed process areas have reportable evidence or assessor-confirmed results yet.</p>`;
    return `<div class="capability-bars">${processes.map(processId=>{const level=reportProcessCapability(project,processId);return `<div class="capability-bar"><strong>${level}</strong><i style="height:${level?level*42:4}%"></i><span>${esc(processId)}</span></div>`}).join("")}</div>`;
  }
  function processRiskTable(project) { return `<table class="official-table"><thead><tr><th>Process Area</th><th>Level</th><th>PA1.1</th><th>PA2.1</th><th>PA2.2</th><th>Evidence</th></tr></thead><tbody>${project.processes.map(processId=>{const items=reportAssessments(project,processId);const coverage=items.length?Math.round(items.reduce((s,a)=>s+(a.evidenceSufficiency?.coverage||0),0)/items.length):0;return `<tr><td>${esc(processReportName(processId))}</td><td><strong>Level ${reportProcessCapability(project,processId)}</strong></td><td>${reportRatingMarkup(reportProcessPaRating(project,processId,"PA 1.1"))}</td><td>${reportRatingMarkup(reportProcessPaRating(project,processId,"PA 2.1"))}</td><td>${reportRatingMarkup(reportProcessPaRating(project,processId,"PA 2.2"))}</td><td>${coverage}%</td></tr>`}).join("")}</tbody></table>`; }
  function assessmentMatrixMarkup(project) {
    const bpCodes=Array.from({length:Math.max(1,...project.processes.map(p=>reportAssessments(project,p,"PA 1.1").length))},(_,i)=>`BP${i+1}`);
    const gpCodes=GP_LIBRARY.map(g=>canonicalCode(g[0]));
    const columns=bpCodes.concat(["PA1.1"],gpCodes.slice(0,6),["PA2.1"],gpCodes.slice(6),["PA2.2"]).flat();
    return `<div class="matrix-scroll"><table class="rating-matrix"><thead><tr><th>Process</th>${columns.map(c=>`<th>${esc(c)}</th>`).join("")}</tr></thead><tbody>${project.processes.map(processId=>`<tr><th>${esc(processId)}</th>${columns.map(code=>{if(code.startsWith("PA"))return `<td>${reportRatingMarkup(reportProcessPaRating(project,processId,code.replace(/^PA/,"PA ")),false)}</td>`;const item=reportAssessments(project,processId).find(a=>a.code===code);return `<td>${item?reportRatingMarkup(item.rating,false):"–"}</td>`}).join("")}</tr>`).join("")}</tbody></table></div>`;
  }
  function reportAssessmentEntry(a, project = null) {
    const breakdown=Object.entries(a.scoreBreakdown||{}).map(([key,value])=>`${({definition:"定义",implementation:"实施",consistency:"一致性",governance:"受控",closure:"闭环"})[key]||key} ${clampScore(value)}`).join(" · ");
    const evidenceAnalysis = project ? reportEvidenceAnalysis(project, a) : [];
    return `<article class="report-assessment-entry"><h4>${reportRatingMarkup(a.rating,false)} ${esc(a.process)}.${esc(a.code)}: ${esc(a.title)} <span class="reviewed-mark">人工已复核</span></h4>${(a.targetIndicators||[]).length?`<div class="indicator-target-line"><strong>Candidate indicator mapping / 候选指标映射：</strong>${(a.targetIndicators||[]).map(value=>`<span class="code-tag">${esc(value)}</span>`).join(" ")}<small> · ${esc(a.mappingStatus||"已由评估师确认")}</small></div>`:""}${a.governance?.owner?`<div class="indicator-target-line"><strong>Governance / 治理：</strong>${esc(a.priority||"P2")} · Owner ${esc(a.governance.owner)} · Due ${esc(a.governance.due||"—")} · ${a.governance.assignment==="proposed"?"建议值，待项目基线确认":"已确认"}</div>`:""}<div class="ai-score-line"><strong>AI 候选 ${esc(a.aiCandidateRating||a.rating)} / 人工结论 ${esc(a.rating)}：</strong>${esc(breakdown)} · 把握度 ${a.confidence}% · ${esc(sufficiencyLabel(a.evidenceSufficiency?.status))} ${a.evidenceSufficiency?.coverage||0}%</div><p>${esc(a.reason)}</p>${(a.findings||[]).map(f=>`<div class="owr-line"><b>${f.type}</b>${esc(f.text)}</div>`).join("")}<div class="evidence-basis"><strong>Evidence basis / 证据依据</strong>${evidenceAnalysis.length?evidenceAnalysis.map(e=>`<div class="report-evidence-row"><b>[${esc(e.evidenceCode)}]</b> ${esc(reportSafeEvidenceSource(e.source))} · ${esc(reportSafeEvidenceLocator(e.locator))} · ${esc(e.strength)}<br><small>${esc(e.originProcess||a.process)} → ${esc(e.targetProcess||a.process)} · ${esc(relationLabel(e.relationType||"direct"))}${e.scopeStatus==="related-only"?" · 关联观察不评级":""}<br>${esc(reportSafeEvidenceExcerpt(e.excerpt))}</small></div>`).join(""):`<div class="report-evidence-row">无可定位证据；评分受护栏限制。</div>`}<div><strong>缺口 / 最小关闭证据：</strong>${esc((a.closureEvidence||[]).join("；")||"由评估师补充确认")}</div>${a.reviewerNote?`<div><strong>人工复核意见：</strong>${esc(a.reviewerNote)}</div>`:""}</div></article>`;
  }
  // v7.7: professional-report General Strengths / Weaknesses / Recommendations,
  // derived from the actual assessment-flow data (evidence → BP/GP → PA → records).
  function processGswrData(project, processId) {
    const items = reportAssessments(project, processId);
    const records = (project.records || []).filter(record => (record.indicators || []).some(key => String(key).startsWith(`${processId}.`)));
    const strengthRecords = records.filter(record => record.type === "strength");
    const weaknessRecords = records.filter(record => record.type === "weakness");
    const recommendationRecords = records.filter(record => record.type === "recommendation");
    const strengths = strengthRecords.map(record => String(record.text || "").trim()).filter(Boolean);
    const weaknesses = weaknessRecords.map(record => { const state = record.closureState && record.closureState !== "已关闭" ? `（弱项状态：${record.closureState}）` : ""; return `${String(record.text || "").trim()}${state}`; }).filter(Boolean);
    const recommendations = recommendationRecords.map(record => String(record.text || "").trim()).filter(Boolean);
    const evidenceLinks = (project.traceLinks || []).filter(link =>
      String(link.indicator || "").startsWith(`${processId}.`)
      && reportEvidenceReferenceAllowed(project, link)
      && items.some(item => indicatorKey(item) === link.indicator)
    );
    const linkedEvidenceIds = new Set(evidenceLinks.map(link => link.evidenceId).filter(Boolean));
    reportEvidenceItems(project).forEach(item => { if ((item.primaryProcesses || []).includes(processId) || item.primaryProcess === processId) linkedEvidenceIds.add(item.id); });
    const direct = evidenceLinks.filter(link => link.strength === "direct").length;
    const ratings = items.map(item => item.rating).filter(Boolean);
    const count = rating => ratings.filter(r => r === rating).length;
    for (const item of items) {
      const key = indicatorKey(item);
      const sufficient = item.evidenceSufficiency?.status === "sufficient";
      if ((RATING_SCORE[item.rating] || 0) >= 85 && sufficient && !strengths.some(text => text.includes(item.code))) {
        strengths.push(`${key} · ${item.title}：评级 ${item.rating}，证据充分${item.reviewed ? "，人工已复核" : "（待人工复核）"}。`);
      }
      if ((RATING_SCORE[item.rating] || 0) < 50 && !weaknesses.some(text => text.includes(item.code))) {
        weaknesses.push(`${key} · ${item.title}：评级 ${item.rating} —— ${item.reason || "未提供能够证明实施的直接证据"}。`);
      } else if (item.evidenceSufficiency && (item.evidenceSufficiency.status === "insufficient" || item.evidenceSufficiency.status === "partial")) {
        const missing = (item.evidenceSufficiency.missingTypes || []).join("、") || "缺少可定位的直接实施证据";
        weaknesses.push(`${key} · 证据${item.evidenceSufficiency.status === "insufficient" ? "不足" : "部分充分"}：${missing}。`);
      }
      for (const suggestion of (item.closureEvidence || [])) {
        if (suggestion && !recommendations.includes(suggestion)) recommendations.push(suggestion);
      }
    }
    const coverage = items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.evidenceSufficiency?.coverage || 0), 0) / items.length) : 0;
    const bpCount = items.filter(item => item.pa === "PA 1.1").length;
    const gpCount = items.length - bpCount;
    const finalCount = records.filter(record => record.status === "Final").length;
    const openWeak = weaknessRecords.filter(record => record.closureState !== "已关闭").length;
    const analysis = [
      `证据解析：${processName(processId)} 关联证据 ${linkedEvidenceIds.size} 份，建立指标—证据关系 ${evidenceLinks.length} 条（direct ${direct} · corroborating ${evidenceLinks.length - direct}）；证据原文与表格行在浏览器本地解析并保留可定位引用。`,
      `逐项评估：BP ${bpCount} 条 / GP ${gpCount} 条 逐项评定并记录评分依据；评分分布 F ${count("F")} · L ${count("L") + count("L+") + count("L-")} · P ${count("P") + count("P+") + count("P-")} · N ${count("N")}。`,
      `PA 聚合：PA 1.1=${reportProcessPaRating(project, processId, "PA 1.1")} · PA 2.1=${reportProcessPaRating(project, processId, "PA 2.1")} · PA 2.2=${reportProcessPaRating(project, processId, "PA 2.2")}；聚合执行硬门禁——任一 N/P 阻止 L，PA 1.1 任一非 F 阻止 F。`,
      `记录合并：评估师记录 优势 ${strengthRecords.length} / 弱项 ${weaknessRecords.length} / 建议 ${recommendationRecords.length} 条${finalCount ? `（其中 ${finalCount} 条已定稿）` : ""}；弱项 ${openWeak} 条仍待关闭。`,
      `结论：${processName(processId)} 能力等级 L${reportProcessCapability(project, processId)}${project.targetLevel ? `（目标 ${project.targetLevel}）` : ""} · 证据覆盖 ${coverage}%。`
    ];
    return { strengths: strengths.slice(0, 8), weaknesses: weaknesses.slice(0, 10), recommendations: recommendations.slice(0, 6), analysis, recordCounts: { s: strengthRecords.length, w: weaknessRecords.length, r: recommendationRecords.length } };
  }
  function gswrBoxMarkup(label, lines, tone) {
    const items = (lines && lines.length) ? lines : ["暂无记录，需评估师在记录合并阶段补充。"];
    return `<div class="report-gswr-block ${tone}"><strong>${esc(label)}:</strong><ul>${items.map(line => `<li>${esc(line)}</li>`).join("")}</ul></div>`;
  }
  function processGswrMarkup(project, processId) {
    const data = processGswrData(project, processId);
    return `<div class="report-process-gswr"><h3>General Strengths, Weaknesses, and Recommendations</h3><p class="report-gswr-intro">The following strengths, weaknesses, and recommendations were identified for ${esc(processReportName(processId))}:</p>${gswrBoxMarkup("Strength", data.strengths, "strength")}${gswrBoxMarkup("Weakness", data.weaknesses, "weakness")}${gswrBoxMarkup("Recommendation", data.recommendations, "recommendation")}<div class="report-analysis-box"><h4>分析过程 / Analysis process</h4><ol>${data.analysis.map(line => `<li>${esc(line)}</li>`).join("")}</ol><p>以上结论来自当前评估工作区的实际数据：证据解析 → 逐项 BP/GP 评估 → PA 硬门禁聚合 → 评估师记录合并 → 关闭门禁，而非模板文本。正式评级仍需评估师最终确认。</p></div></div>`;
  }
  function generalGswrMarkup(project) {
    const per = project.processes.map(processId => processGswrData(project, processId));
    const strengths = [...new Set(per.flatMap(p => p.strengths))].slice(0, 12);
    const weaknesses = [...new Set(per.flatMap(p => p.weaknesses))].slice(0, 14);
    const recommendations = [...new Set(per.flatMap(p => p.recommendations))].slice(0, 10);
    return `<h2 class="report-section-title">2.4 General Strengths, Weaknesses, and Recommendations</h2><p class="report-gswr-intro">The following strengths, weaknesses, and recommendations were identified across the formal assessment scope:</p>${gswrBoxMarkup("Strength", strengths, "strength")}${gswrBoxMarkup("Weakness", weaknesses, "weakness")}${gswrBoxMarkup("Recommendation", recommendations, "recommendation")}`;
  }
  function processDetailedReport(project,processId,index) {
    const bp=reportAssessments(project,processId,"PA 1.1");const gp21=reportAssessments(project,processId,"PA 2.1");const gp22=reportAssessments(project,processId,"PA 2.2");
    return reportSheet(project,`Detailed Results · ${processId}`,`<h2 class="report-section-title">3.${index+1} ${esc(processReportName(processId))} <small>Capability Level ${reportProcessCapability(project,processId)}</small></h2><h3>Scope limitations</h3><p>n/a —— 正式范围固定为 ${esc(project.processes.map(processReportName).join("、"))}；范围外过程仅形成关联观察，不进入评级。</p><h3>Level 1 Results</h3><h4>BPs - Base Practices</h4><ul class="report-bp-list">${bp.map(a=>`<li>${reportRatingMarkup(a.rating,false)} <strong>${esc(a.code)}:</strong> ${esc(a.title)}</li>`).join("")}</ul><div class="report-pa-line">PA1.1 - Process performance process attribute · ${reportRatingMarkup(reportProcessPaRating(project,processId,"PA 1.1"))}</div>${bp.map(a=>reportAssessmentEntry(a,project)).join("")}<h3>Level 2 Results</h3><h4>PA2.1 - Performance management process attribute · ${reportRatingMarkup(reportProcessPaRating(project,processId,"PA 2.1"))}</h4>${gp21.map(a=>reportAssessmentEntry(a,project)).join("")}<h4>PA2.2 - Work product management process attribute · ${reportRatingMarkup(reportProcessPaRating(project,processId,"PA 2.2"))}</h4>${gp22.map(a=>reportAssessmentEntry(a,project)).join("")}${processGswrMarkup(project,processId)}`,"detail-sheet");
  }
  function crossProcessReportMarkup(project) {
    const method=reportSheet(project,"Cross-Process Analysis Method",`<h2 class="report-section-title">2.5 Cross-Process Analysis / 跨过程分析</h2><p>AI 对每份证据先在本地读取正文、表格和 Helix 对象字段，识别主过程及稳定行定位，再执行四遍关系扫描。范围内过程进入 BP/GP 正式评分；范围外过程仅形成“关联观察·不评级”。关联证据可以证明接口一致性，但不能替代目标过程的直接实施证据。</p><table class="official-table"><thead><tr><th>Pass</th><th>分析问题</th></tr></thead><tbody>${CROSS_PROCESS_PASSES.map((item,index)=>`<tr><td>${index+1}. ${esc(item[1])}</td><td>${esc(item[2])}</td></tr>`).join("")}</tbody></table><div class="report-disclaimer">关系模型重点覆盖需求—设计—实现—验证价值链，以及 MAN.3 项目接口和计划、SUP.1 质量保证、SUP.8 配置完整性、SUP.9 问题闭环、SUP.10 变更影响与双向追溯。Helix 表格按 ID、状态、责任、版本/基线、上下游链接、影响与关闭字段联合判断；仅有链接或 Closed 状态不会自动证明闭环有效。</div>`);
    const details=project.processes.map((processId,index)=>{
      const rows=visibleCrossRows(project,processId);
      return reportSheet(project,`Cross-Process · ${processId}`,`<h2 class="report-section-title">2.5.${index+1} ${esc(processName(processId))} 关系分析</h2><table class="official-table cross-process-report-table"><thead><tr><th>接口</th><th>关系 / 范围</th><th>分析遍次</th><th>证据</th><th>AI 分析过程</th><th>风险与跟进</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.sourceProcess)} → ${esc(row.targetProcess)}</td><td>${esc(relationLabel(row.relationType))}<br><small>${row.scopeStatus==="in-scope"?"正式范围":"关联观察·不评级"}</small></td><td>${row.analysisPasses.map(pass=>esc(CROSS_PROCESS_PASSES.find(item=>item[0]===pass)?.[1]||pass)).join("；")}</td><td>${row.evidenceCodes.map(code=>`[${esc(code)}]`).join(" ")||"未覆盖"}</td><td>${esc(row.supportedClaim)}<br><small>${esc(row.gapOrRisk)}</small></td><td>${esc(row.followUp)}</td></tr>`).join("")}</tbody></table>`);
    }).join("");
    return method+details;
  }
  function traceabilityReportMarkup(project) {
    const coverage=reportTraceCoverage(project);
    const reportable = (project.assessments || []).filter(item => isReportableAssessment(item, project));
    return reportSheet(project,"Indicator–Evidence Trace Matrix",`<h2 class="report-section-title">2.6 Indicator–Evidence Trace Matrix / 指标—证据追溯矩阵</h2><p>矩阵记录已由评估师确认的 BP/GP—证据关系。Direct 只表示证据属于目标过程且存在可定位正文或表格；Corroborating 仅用于核实上下游接口、MAN.3、SUP.1、SUP.8、SUP.9 或 SUP.10 的一致性与闭环，不替代目标过程实施证据。</p><div class="report-risk-grid"><div><span>指标有关系</span><strong>${coverage.linked}/${coverage.total}</strong></div><div><span>直接覆盖</span><strong>${coverage.directPercent}%</strong></div><div><span>人工确认</span><strong>${coverage.confirmed}</strong></div><div><span>无关系缺口</span><strong>${coverage.gaps}</strong></div></div><table class="official-table trace-report-matrix"><thead><tr><th>Indicator</th><th>AI / Human rating</th><th>Direct evidence</th><th>Corroborating / related</th><th>Assessor-confirmed</th><th>Gap, risk &amp; next evidence</th></tr></thead><tbody>${reportable.map(assessment=>{const links=reportTraceLinksForAssessment(project,assessment);const direct=links.filter(link=>link.strength==="direct");const related=links.filter(link=>link.strength!=="direct");const confirmed=links.filter(link=>link.confirmed);const cite=items=>items.map(link=>`<b>[${esc(link.evidenceCode||"EV")}]</b> ${esc(reportSafeEvidenceLocator(link.locator,"证据定位"))}`).join("<br>")||"—";return `<tr><td><strong>${esc(indicatorKey(assessment))}</strong><br><small>${esc(assessment.title)}</small></td><td>${reportRatingMarkup(assessment.aiCandidateRating||assessment.rating,false)} / ${reportRatingMarkup(assessment.rating,false)}<br><small>人工已复核</small></td><td>${cite(direct)}</td><td>${cite(related)}</td><td>${confirmed.length?confirmed.map(link=>`[${esc(link.evidenceCode||"EV")}] ${esc(reportSafeNarrative(link.creator,"评估师"))}`).join("<br>"):"—"}</td><td>${esc(reportSafeNarrative((assessment.evidenceSufficiency?.missingTypes||[]).join("；")||(assessment.closureEvidence||[]).slice(0,2).join("；"),"需确认代表性与跨版本稳定性"))}</td></tr>`}).join("")}</tbody></table><div class="report-disclaimer">AI 分析过程：证据解析 → 主过程识别 → BP/GP 适配 → direct / corroborating / index-only 分类 → 上下游与治理支撑过程四遍扫描 → 证据充分性限分 → 评估师确认关系和最终评分。人工确认关系不会自动提高评分，也不会把范围外过程纳入正式评级。</div>`);
  }
  function actionPlanAppendixMarkup(project) {
    const issues=project.actionPlanIssues||[];
    if(!issues.length)return "";
    const severityCount=severity=>issues.filter(item=>String(item.severity).toLowerCase()===severity.toLowerCase()).length;
    const missingOwners=issues.filter(item=>!item.owner||item.owner==="—").length;
    const missingDue=issues.filter(item=>!item.due||item.due==="—").length;
    const row=issue=>`<tr><td>${esc(issue.issue)}</td><td>${esc(reportSafeNarrative(issue.process, "待确认过程"))}</td><td>${esc(reportSafeNarrative((issue.targetIndicators||[]).join("、"), "待确认"))}<br><small>${esc(reportSafeNarrative(issue.mappingStatus, "待评估师确认"))}</small></td><td>${esc(reportSafeNarrative(issue.theme, "—"))}</td><td>${esc(reportSafeNarrative(issue.priority, "P2"))} / ${esc(reportSafeNarrative(issue.severity, "待确认"))}</td><td>${esc(reportSafeNarrative(issue.auditExplanation||issue.originalProblem, "待评估师确认"))}<br><small>${esc(reportSafeNarrative(issue.risk, "待评估师确认"))}</small></td><td>${esc(reportSafeNarrative((issue.closureEvidence||[]).join("；"), "待评估师定义"))}<br><small>${esc(reportSafeNarrative(issue.closureRule, "待评估师定义"))}</small></td><td>${esc(reportSafeNarrative(issue.owner, "—"))} / ${esc(reportSafeNarrative(issue.due, "—"))}<br><small>建议值，待项目基线确认</small></td></tr>`;
    return reportSheet(project,"CEP Action Plan Appendix",`<h2 class="report-section-title">7. CEP Action Plan Issue Register / 整改问题清单</h2><div class="report-disclaimer">本附录来自 ${esc(reportSafeImportedSource(project.actionPlanSourceFile, "Controlled action-plan input / 受控整改输入"))}。Action Plan、评估纪要和 OPL 记录属于评估输入或佐证，能够说明问题被识别，但不能替代目标过程的直接实施证据，也不能单独证明整改已经关闭。关闭应同时证明：组织标准已更新、项目已采用、结果已评审、问题已验证关闭。</div><div class="report-risk-grid"><div><span>Open issues</span><strong>${issues.length}</strong></div><div><span>Major / Minor</span><strong>${severityCount("Major")} / ${severityCount("Minor")}</strong></div><div><span>Owner missing</span><strong>${missingOwners}</strong></div><div><span>Due missing</span><strong>${missingDue}</strong></div></div><table class="official-table"><thead><tr><th>Issue</th><th>Source process</th><th>Candidate indicators</th><th>Work product / Topic</th><th>Priority / Severity</th><th>Assessment opinion / Risk</th><th>Minimum closure evidence / Rule</th><th>Owner / Due</th></tr></thead><tbody>${issues.map(row).join("")}</tbody></table><div class="report-disclaimer">证据护栏：Direct 证据必须可定位到受控项目工作产品；Corroborating 证据只用于支持接口、依赖、一致性或闭环；Index-only 只能证明文件或记录存在。相关过程证据不能替代目标过程直接证据，AI 输出为候选结论，须由评估师复核。</div>`);
  }

  function formalReportMarkupEnglish(project) {
    refreshProjectOutcome(project);
    project = {
      ...project,
      assessments: (project.assessments || []).filter(item => isReportableAssessment(item, project)),
      evidence: reportEvidenceItems(project)
    };
    const quality = assessmentQuality(project);
    const final = project.importSource ? project.status === "complete" : project.assessmentState === "Closed" && quality.ready;
    const assessments = project.assessments;
    const reviewed = assessments.length;
    const weaknesses = assessments.filter(item => (RATING_SCORE[item.rating] || 0) < 50);
    const reportCoverage = reportTraceCoverage(project);
    const processLabel = processId => processReportName(processId);
    const processCapability = (currentProject, processId) => reportProcessCapability(currentProject, processId);
    const processPaRating = (currentProject, processId, pa) => reportProcessPaRating(currentProject, processId, pa);
    const processAssessments = (currentProject, processId, pa) => reportAssessments(currentProject, processId, pa);
    const assessmentMarkup = item => {
      const key = indicatorKey(item);
      const title = localizedField(item, "title", item.title || "Assessment item");
      const reason = localizedField(item, "reason", item.reason || "No rationale recorded.");
      const closure = localizedList(item, "closureEvidence");
      const finding = (item.findings || []).map(item => localizedField(item, "text", item.text || "")).filter(Boolean).join("; ");
      const evidence = reportEvidenceAnalysis(project, item).map(entry => `<div class="report-evidence-row"><b>[${esc(entry.evidenceCode || "EV")}]</b> ${esc(reportSafeEvidenceSource(localizedField(entry, "source", entry.source || "Evidence"), "Assessor-confirmed evidence"))} · ${esc(reportSafeEvidenceLocator(englishLocator(entry.locator || "Locator required"), "Evidence locator"))} · ${esc(evidenceStrengthText(entry.strength || "direct"))}<br><small>${esc(entry.originProcess || item.process)} → ${esc(entry.targetProcess || item.process)} · ${esc(relationLabelEnglish(entry.relationType || "direct"))}<br><span data-i18n-evidence>${esc(reportSafeEvidenceExcerpt(localizedField(entry, "excerpt", entry.excerpt || ""), "Controlled evidence excerpt"))}</span></small></div>`).join("") || `<div class="report-evidence-row">No locatable evidence; the rating is constrained by the evidence guardrail.</div>`;
      return `<article class="report-assessment-entry"><h4>${reportRatingMarkup(item.rating, false)} ${esc(item.process)}.${esc(item.code)}: ${esc(title)} ${item.reviewed ? `<span class="reviewed-mark">Assessor reviewed</span>` : `<span class="draft-mark">Awaiting assessor review</span>`}</h4><div class="ai-score-line"><strong>AI candidate ${esc(item.aiCandidateRating || item.rating)} / human conclusion ${esc(item.rating)}</strong> · confidence ${Number(item.confidence || 0)}% · ${esc(sufficiencyLabel(item.evidenceSufficiency?.status))} ${item.evidenceSufficiency?.coverage || 0}%</div><p>${esc(reason)}</p>${finding ? `<div class="owr-line"><b>Finding</b> ${esc(finding)}</div>` : ""}<div class="evidence-basis"><strong>Evidence basis</strong>${evidence}<div><strong>Gap / minimum closure evidence:</strong> ${esc(closure.join("; ") || "To be confirmed by the assessor")}</div>${item.reviewerNote ? `<div><strong>Assessor note:</strong> ${esc(localizedField(item, "reviewerNote", item.reviewerNote))}</div>` : ""}</div></article>`;
    };
    const assessmentRows = assessments.map(assessmentMarkup).join("");
    const cover = reportSheet(project, "Cover", `<div class="report-status-stamp ${final ? "final" : ""}">${final ? "FINAL" : "CONTROLLED DRAFT"}</div><p class="report-blue-label">Automotive SPICE Process Assessment</p><h1 class="report-title">${esc(localizedField(project, "organization", project.organization))}<br>Process assessment report</h1><p class="report-subtitle">${esc(localizedField(project, "name", project.name))} · ${esc(localizedField(project, "product", project.product))}</p><table class="official-table report-cover-table"><tbody>${[["Company", localizedField(project, "organization", project.organization), "Project", localizedField(project, "name", project.name)], ["Product", localizedField(project, "product", project.product), "PAM version", project.pam], ["Target / achieved level", `${project.targetLevel} / ${project.achievedLevel}`, "Assessment date", formatDate(project.date)], ["Report number", project.reportNo, "Class / type / category", `${project.attributes?.assessmentClass || "Class 2"} / Process assessment / AI-assisted`], ["Lead assessor", project.owner, "Assessors", (project.participants || []).map(person => person.name).join(", ") || project.owner]].map(row => `<tr>${row.map((cell, index) => `<${index % 2 === 0 ? "th" : "td"}>${esc(cell)}</${index % 2 === 0 ? "th" : "td"}>`).join("")}</tr>`).join("")}</tbody></table><h2>Assessment scope and capability level</h2>${capabilityChartMarkup(project)}<div class="report-signatures"><div>Lead assessor</div><div>Project representative</div><div>Quality representative</div></div>`, "cover-sheet");
    const processRows = project.processes.map(processId => { const items = reportAssessments(project, processId); const coverage = items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.evidenceSufficiency?.coverage || 0), 0) / items.length) : 0; return `<tr><td>${esc(processLabel(processId))}</td><td>Level ${reportProcessCapability(project, processId)}</td><td>${reportRatingMarkup(reportProcessPaRating(project, processId, "PA 1.1"))}</td><td>${reportRatingMarkup(reportProcessPaRating(project, processId, "PA 2.1"))}</td><td>${reportRatingMarkup(reportProcessPaRating(project, processId, "PA 2.2"))}</td><td>${coverage}%</td></tr>`; }).join("");
    const executiveOpinionRaw = englishDisplayText(buildExecutiveOpinion(project));
    const executiveOpinion = executiveOpinionRaw === "Untranslated interface text"
      ? "This assessment summary is based on the current evidence chain, candidate ratings, and pending assessor confirmation."
      : executiveOpinionRaw;
    const summary = reportSheet(project, "Summary", `<h2 class="report-section-title">2. Summary</h2>${project.importSource ? `<div class="report-disclaimer"><strong>Imported professional assessment:</strong> ${esc(reportSafeImportedSource(project.importSource.sourceFile, "Controlled imported assessment"))} · ${esc(project.importSource.reportVersion || "")} · ${esc(project.importSource.assessmentPeriod || "")}. Import completion does not mean every process achieved its target capability level.</div>` : ""}<h3>2.1 Management summary</h3><p>${esc(executiveOpinion)}</p><div class="report-risk-grid"><div><span>Achieved level</span><strong>${esc(project.achievedLevel)}</strong></div><div><span>Weakness candidates</span><strong>${weaknesses.length}</strong></div><div><span>Evidence coverage</span><strong>${reportCoverage.directPercent}%</strong></div><div><span>Assessor review</span><strong>${Math.round(reviewed / Math.max(1, assessments.length) * 100)}%</strong></div></div><h3>2.2 Assumptions and constraints</h3><ul><li>AI candidates use only registered evidence associated with the formal process scope.</li><li>File names and metadata alone are not direct implementation evidence.</li><li>Unreviewed, insufficient or non-finalised items cannot pass the closure quality gate.</li></ul><h3>2.3 Risk dashboard</h3><table class="official-table"><thead><tr><th>Process area</th><th>Level</th><th>PA1.1</th><th>PA2.1</th><th>PA2.2</th><th>Evidence</th></tr></thead><tbody>${processRows}</tbody></table><h3>2.4 General strengths, weaknesses and recommendations</h3><p>See the item-level findings and assessor records below. AI-generated text remains advisory until the assessor confirms it.</p>`);
    const matrix = reportSheet(project, "BP / PA / GP Matrix", `<h2 class="report-section-title">2.5 BP / PA / GP rating matrix</h2><div class="matrix-scroll"><table class="rating-matrix"><thead><tr><th>Process</th>${GP_LIBRARY.map(item => `<th>${esc(canonicalCode(item[0]))}</th>`).join("")}</tr></thead><tbody>${project.processes.map(processId => `<tr><th>${esc(processLabel(processId))}</th>${GP_LIBRARY.map(item => { const assessment = reportAssessments(project, processId).find(candidate => canonicalCode(candidate.code) === canonicalCode(item[0])); return `<td>${assessment ? reportRatingMarkup(assessment.rating, false) : "–"}</td>`; }).join("")}</tr>`).join("")}</tbody></table></div>`);
    const traceRows = assessments.map(item => { const links = reportTraceLinksForAssessment(project, item); const direct = links.filter(link => link.strength === "direct"); const related = links.filter(link => link.strength !== "direct"); const cite = entries => entries.map(link => `<b>[${esc(link.evidenceCode || "EV")}]</b> ${esc(reportSafeEvidenceLocator(englishLocator(link.locator || "Locator required"), "Evidence locator"))}`).join("<br>") || "—"; return `<tr><td><strong>${esc(indicatorKey(item))}</strong><br><small>${esc(localizedField(item, "title", item.title || "Assessment item"))}</small></td><td>${reportRatingMarkup(item.aiCandidateRating || item.rating, false)} / ${reportRatingMarkup(item.rating, false)}<br><small>Assessor reviewed</small></td><td>${cite(direct)}</td><td>${cite(related)}</td><td>${links.filter(link => link.confirmed).length || 0}</td><td>${esc(localizedList(item.evidenceSufficiency, "missingTypes").join("; ") || localizedList(item, "closureEvidence").slice(0, 2).join("; ") || "Confirm representativeness and cross-version stability")}</td></tr>`; }).join("");
    const traceability = reportSheet(project, "Indicator–Evidence Trace Matrix", `<h2 class="report-section-title">2.6 Indicator–evidence trace matrix</h2><p>The matrix records AI-inferred and assessor-confirmed BP/GP-to-evidence relationships. Direct evidence must be locatable and belong to the target process; corroborating evidence supports interfaces and governance but cannot replace implementation evidence.</p><table class="official-table trace-report-matrix"><thead><tr><th>Indicator</th><th>AI / human rating</th><th>Direct evidence</th><th>Corroborating / related</th><th>Assessor-confirmed</th><th>Gap, risk and next evidence</th></tr></thead><tbody>${traceRows}</tbody></table>`);
    const details = project.processes.map(processId => reportSheet(project, `Detailed Results · ${processId}`, `<h2 class="report-section-title">${esc(processLabel(processId))} <small>Capability level ${processCapability(project, processId)}</small></h2><h3>Scope limitations</h3><p>The formal scope is limited to ${esc(project.processes.map(processLabel).join(", "))}; out-of-scope processes provide context only.</p><h3>Assessment results</h3>${assessments.filter(item => item.process === processId).map(assessmentMarkup).join("") || `<div class="empty-mini">No assessment items.</div>`}`, "detail-sheet")).join("");
    const workProducts = reportSheet(project, "Work Products / Final Remark", `<h2 class="report-section-title">3. Assessed work products</h2><table class="official-table"><thead><tr><th>No.</th><th>ID</th><th>Primary process</th><th>Related context</th><th>Name / structure</th><th>Helix readout</th><th>Reference quality</th></tr></thead><tbody>${(project.evidence || []).map((evidence, index) => { const primary = inferEvidencePrimaryProcesses(evidence, project.processes); const locatable = String(evidence.content || "").trim().length >= 120 || (evidence.tables || []).some(table => table.rowCount); const primaryLabel = primary.map(processLabel).join(", ") || englishDisplayText(evidence.scope || "Unclassified"); return `<tr><td>${index + 1}</td><td>${esc(evidence.code || `EV.${String(index + 1).padStart(3, "0")}`)}</td><td>${esc(primaryLabel)}</td><td>${esc((evidence.relatedProcesses || []).map(processLabel).join(", ") || "—")}</td><td>${esc(reportSafeEvidenceSource(localizedField(evidence, "name", evidence.name || ""), "Assessor-confirmed evidence"))}<br><small>${esc(reportSafeEvidenceSource(localizedField(evidence, "structure", evidence.structure || evidence.source || "Local upload"), "Controlled evidence"))}</small></td><td>${evidence.helix?.detected ? `${evidence.helix.tableCount} tables / ${evidence.helix.rowCount} rows / ${evidence.helix.linkedRows} linked rows` : "—"}</td><td>${locatable ? "Locatable text/table" : "Metadata only"}</td></tr>`; }).join("")}</tbody></table><h2 class="report-section-title">4. Findings and improvement roadmap</h2><table class="official-table"><thead><tr><th>Priority</th><th>Indicator</th><th>Weakness / risk</th><th>Minimum closure evidence</th><th>Owner / due</th></tr></thead><tbody>${weaknesses.slice(0, 30).map((item, index) => `<tr><td>${index < 5 ? "P1" : "P2"}</td><td>${esc(indicatorKey(item))}</td><td>${esc(reportSafeNarrative(localizedField(item.findings?.find(finding => finding.type === "W") || item, "text", item.reason || ""), "Assessor confirmation required"))}</td><td>${esc(reportSafeNarrative(localizedList(item, "closureEvidence").join("; "), "To be defined by the assessor"))}</td><td>Unassigned</td></tr>`).join("") || `<tr><td colspan="5">No weakness candidates.</td></tr>`}</tbody></table><h2 class="report-section-title">5. Final remark</h2><div class="report-disclaimer">This report combines local evidence parsing, direct-evidence guardrails, cross-process analysis and assessor review status for internal process improvement. Related-process evidence remains corroborating and AI output remains a candidate until an appropriately independent assessor confirms the conclusion. ${final ? "The current version passed the internal quality gate." : "The current version is a controlled draft with outstanding review or evidence gaps."}</div>`);
    const actionPlanIssues = project.actionPlanIssues || [];
    const actionPlan = actionPlanIssues.length ? reportSheet(project, "CEP Action Plan Appendix", `<h2 class="report-section-title">6. CEP action-plan issue register</h2><p>Action-plan and OPL records identify issues and remediation context; they do not replace direct implementation evidence or prove closure on their own.</p><table class="official-table"><thead><tr><th>Issue</th><th>Source process</th><th>Candidate indicators</th><th>Priority / severity</th><th>Assessment opinion / risk</th><th>Minimum closure evidence</th><th>Owner / due</th></tr></thead><tbody>${actionPlanIssues.map(issue => `<tr><td>${esc(issue.issue || issue.id || "Issue")}</td><td>${esc(reportSafeNarrative(englishDisplayText(issue.process || ""), "Process to be confirmed"))}</td><td>${esc(reportSafeNarrative((issue.targetIndicators || []).map(value => englishDisplayText(value)).join(", "), "To be confirmed"))}</td><td>${esc(reportSafeNarrative(issue.priority, "P2"))} / ${esc(reportSafeNarrative(issue.severity, "To be confirmed"))}</td><td>${esc(reportSafeNarrative(localizedField(issue, "auditExplanation", issue.auditExplanation || issue.originalProblem || ""), "Assessor confirmation required"))}<br><small>${esc(reportSafeNarrative(localizedField(issue, "risk", issue.risk || ""), "Assessor confirmation required"))}</small></td><td>${esc(reportSafeNarrative(localizedList(issue, "closureEvidence").join("; "), "To be defined by the assessor"))}</td><td>${esc(reportSafeNarrative(issue.owner, "Unassigned"))} / ${esc(reportSafeNarrative(issue.due || issue.dueDate, "—"))}</td></tr>`).join("")}</tbody></table>`, "appendix-sheet") : "";
    return cover + summary + matrix + traceability + details + workProducts + actionPlan;
  }

  function formalReportMarkup(project) {
    if (currentLanguage() === "en") return formalReportMarkupEnglish(project);
    refreshProjectOutcome(project);
    project={...project,assessments:(project.assessments||[]).filter(item=>isReportableAssessment(item,project)),evidence:reportEvidenceItems(project)};
    const quality=assessmentQuality(project);const final=project.importSource?project.status==="complete":project.assessmentState==="Closed"&&quality.ready;
    const weak=project.assessments.filter(a=>RATING_SCORE[a.rating]<50);const reviewed=Math.round(project.assessments.filter(a=>a.reviewed).length/Math.max(1,project.assessments.length)*100);
    const cover=reportSheet(project,"Cover",`<div class="report-status-stamp ${final?"final":""}">${final?"FINAL / 已定稿":"CONTROLLED DRAFT / 受控草稿"}</div><p class="report-blue-label">Automotive SPICE Process Assessment</p><h1 class="report-title">${esc(project.organization)}<br>过程评估报告</h1><p class="report-subtitle">${esc(project.name)} · ${esc(project.product)}</p><table class="official-table report-cover-table"><tbody>${[["Company",project.organization,"Project",project.name],["Product",project.product,"PAM Version",project.pam],["Target / Achieved Level",`${project.targetLevel} / ${project.achievedLevel}`,"Assessment Date",formatDate(project.date)],["Report No.",project.reportNo,"Class / Type / Category",`${project.attributes?.assessmentClass||"Class 2"} / Process Assessment / AI 辅助评估`],["Lead Assessor",project.owner,"Assessors",(project.participants||[]).map(p=>p.name).join("、")||project.owner]].map(row=>`<tr>${row.map((cell,i)=>`<${i%2===0?"th":"td"}>${esc(cell)}</${i%2===0?"th":"td"}>`).join("")}</tr>`).join("")}</tbody></table><h2>Assessment Scope and Capability Level</h2>${capabilityChartMarkup(project)}<div class="report-signatures"><div>Lead Assessor</div><div>Project Representative</div><div>Quality Representative</div></div>`,`cover-sheet`);
        const tocRow=(no,title,target)=>`<tr><td>${no}</td><td>${title}</td><td class="toc-page" data-toc-target="${esc(target)}">—</td></tr>`;
    const contents=reportSheet(project,"Contents / Background",`<h2 class="report-section-title">Contents</h2><table class="toc-table"><thead><tr><th>No.</th><th>Section</th><th>Page</th></tr></thead><tbody>${tocRow("1","Background","Contents / Background")}${tocRow("2","Summary","Summary")}${tocRow("2.1","Management Summary","Summary")}${tocRow("2.2","Assumptions &amp; Constraints","Summary")}${tocRow("2.3","Risk Dashboard","Summary")}${tocRow("2.4","General Strengths, Weaknesses, and Recommendations","Summary")}${tocRow("2.5","Cross-Process Analysis Method &amp; Results","Cross-Process Analysis Method")}${tocRow("2.6","Indicator–Evidence Trace Matrix","Indicator–Evidence Trace Matrix")}${tocRow("2.7","BP / PA / GP 评级矩阵","BP / PA / GP Matrix")}${tocRow("3","Detailed Results",`Detailed Results · ${project.processes[0]||""}`)}${project.processes.map((p,i)=>tocRow(`3.${i+1}`,processReportName(p),`Detailed Results · ${p}`)).join("")}${tocRow("4","Assessed Work Products","Work Products / Final Remark")}${tocRow("5","Findings &amp; Improvement Roadmap","Work Products / Final Remark")}${tocRow("6","Final Remark","Work Products / Final Remark")}${project.actionPlanIssues?.length?tocRow("7","CEP Action Plan Issue Register","CEP Action Plan Appendix"):""}</tbody></table><h2 class="report-section-title">1. Background</h2><table class="official-table"><tbody>${[["Assessment Date",formatDate(project.date)],["Company",project.organization],["Project / Product",`${project.name} / ${project.product}`],["Assessment Team",(project.participants||[]).map(p=>`${p.name}（${p.role}）`).join("、")],["PAM Version",project.pam],["Assessment Class",project.attributes?.assessmentClass||"Class 2"],["Target / Achieved Level",`${project.targetLevel} / ${project.achievedLevel}`],["Formal Assessment Scope",project.processes.map(processReportName).join("、")],["Related Context","上游、下游、MAN.3、SUP.1、SUP.8、SUP.9、SUP.10（范围外不评级）"],["Objective","评估所选过程在 Automotive SPICE 下的过程能力，并沿过程接口识别风险、证据缺口与最小改进闭环。"]].map(row=>`<tr><th>${esc(row[0])}</th><td>${esc(row[1])}</td></tr>`).join("")}</tbody></table>`);
    const summary=reportSheet(project,"Summary",`<h2 class="report-section-title">2. Summary</h2>${project.importSource?`<div class="report-disclaimer"><strong>Imported professional assessment:</strong> ${esc(reportSafeImportedSource(project.importSource.sourceFile, "受控导入评估输入"))} · ${esc(project.importSource.reportVersion)} · ${esc(project.importSource.assessmentPeriod)}. Progress 100% means the assessment activity and import are complete; it does not mean all ASPICE processes achieved the target capability level.</div>`:""}<h3>2.1 Management Summary</h3><p>${esc(reportSafeNarrative(buildExecutiveOpinion(project), "待评估师确认管理摘要"))}</p><div class="report-risk-grid"><div><span>Achieved Level</span><strong>${esc(project.achievedLevel)}</strong></div><div><span>Weakness candidate</span><strong>${weak.length}</strong></div><div><span>Evidence coverage</span><strong>${quality.coverage}%</strong></div><div><span>Human review</span><strong>${reviewed}%</strong></div></div><h3>2.2 Assumptions &amp; Constraints</h3><ul><li>AI 仅基于当前登记且与过程范围关联的证据生成候选结论。</li><li>仅文件名或元数据命中的证据不会被当作项目实施的直接证明。</li><li>未复核、证据不足或记录未定稿的条目不会通过关闭质量门禁。</li></ul><h3>2.3 Risk Dashboard</h3>${processRiskTable(project)}${generalGswrMarkup(project)}`);
    
    const matrix=reportSheet(project,"BP / PA / GP Matrix",`<h2 class="report-section-title">BP / PA / GP 评级矩阵</h2>${assessmentMatrixMarkup(project)}<div class="rating-legend report-legend">${RATING_ORDER.map(r=>`<div>${reportRatingMarkup(r)}</div>`).join("")}</div>`);const crossProcess=crossProcessReportMarkup(project);
    const traceability=traceabilityReportMarkup(project);
    const details=project.processes.map((processId,index)=>processDetailedReport(project,processId,index)).join("");
    const workProducts=reportSheet(project,"Work Products / Final Remark",`<h2 class="report-section-title">4. Assessed Work Products</h2><table class="official-table"><thead><tr><th>No.</th><th>ID</th><th>Primary Process</th><th>Related Context</th><th>Name / Structure</th><th>Helix Table Readout</th><th>Reference quality</th></tr></thead><tbody>${project.evidence.map((e,index)=>{const primary=inferEvidencePrimaryProcesses(e,project.processes);const related=[...new Set(primary.flatMap(processId=>relatedProcessesFor(processId,project.processes).map(row=>row.relatedProcess)))].filter(p=>(project.processes||[]).includes(p));const locatable=String(e.content||"").trim().length>=120||(e.tables||[]).some(table=>table.rowCount);return `<tr><td>${index+1}</td><td>${esc(e.code||`EV.${String(index+1).padStart(3,"0")}`)}</td><td>${esc(primary.join("、")||e.scope||"未识别")}</td><td>${esc(related.join("、")||"—")}</td><td>${esc(reportSafeEvidenceSource(e.name,"受控评估输入"))}<br><small>${esc(reportSafeEvidenceSource(e.structure||e.source||"本地上传","受控证据"))}</small></td><td>${e.helix?.detected?`${e.helix.tableCount} 表 / ${e.helix.rowCount} 行 / ${e.helix.linkedRows} 关系行<br><small>${esc(reportSafeNarrative((e.helix.fields||[]).join("、"),"受控表格字段"))}</small>`:"—"}</td><td>${locatable?"Locatable text/table / 可定位正文或表格":"Metadata only / 待定位"}</td></tr>`;}).join("")}</tbody></table><h2 class="report-section-title">5. Findings &amp; Improvement Roadmap</h2><table class="official-table"><thead><tr><th>Priority</th><th>Indicator</th><th>Weakness / Risk</th><th>Minimum closure evidence</th><th>Owner / Due</th></tr></thead><tbody>${project.assessments.filter(a=>(a.findings||[]).some(f=>f.type==="W")).slice(0,30).map((a,index)=>`<tr><td>${index<5?"P1":"P2"}</td><td>${esc(indicatorKey(a))}</td><td>${esc(reportSafeNarrative(a.findings.find(f=>f.type==="W")?.text||a.reason,"待评估师确认") )}</td><td>${esc(reportSafeNarrative((a.closureEvidence||[]).join("；"),"待评估师定义"))}</td><td>待分配</td></tr>`).join("")||`<tr><td colspan="5">当前没有弱项候选。</td></tr>`}</tbody></table><h2 class="report-section-title">6. Final Remark</h2><div class="report-disclaimer">本报告由 AuditFlow AI 生成，逐项评级包含 AI 初评、本地 Office/PDF 与 Helix 表格解析、直接证据充分性护栏、跨过程四遍分析和人工复核状态，供内部过程改进与能力提升参考。范围外关联过程只形成观察，不构成正式评级；跨过程证据不能替代目标过程直接证据。若需作为正式评估或认证结论，应由具备适用资质、权限与独立性的评估师基于完整证据复核确认。${final?"当前版本已通过本工具的内部质量门禁。":"当前版本仍为受控草稿，存在未复核或证据充分性缺口。"}</div>`);
    const actionPlanAppendix=actionPlanAppendixMarkup(project);
    return cover+contents+summary+matrix+crossProcess+traceability+details+workProducts+actionPlanAppendix;
  }
  function renderReport(project) {
    if (!project) return renderNotFound();
    refreshProjectOutcome(project);const quality=assessmentQuality(project);project=localizedProject(deepCopy(project));(project.assessments||[]).forEach(item=>{if((item.targetIndicators||[]).length&&!item.mappingCalibrated)item.targetIndicators=[];});
    const reportMarkup = formalReportMarkup(project);
    const reportStatus = currentLanguage() === "en" ? (project.importSource ? "Imported professional assessment" : quality.ready ? "Report quality gate passed" : "Controlled draft with evidence or review gaps") : (project.importSource ? "专业评估报告已导入" : quality.ready ? "报告门禁通过" : "受控草稿，仍有证据/复核缺口");
    app.innerHTML = `<div class="page">${renderPageHead("Formal Audit Report", currentLanguage()==="en" ? "Automotive SPICE process assessment report" : "Automotive SPICE 过程评估报告", `${project.reportNo} · ${reportStatus}`, `<button class="btn secondary" data-action="open-standard-project" data-id="${project.id}">${uiText("返回项目", "Back to project")}</button><button class="btn secondary" data-action="export-word-standard" data-id="${project.id}">${icon("download")}${uiText("导出 Word", "Export Word")}</button><button class="btn secondary" data-action="export-ppt-standard" data-id="${project.id}">${icon("download")}${uiText("导出 PPT", "Export PPT")}</button><button class="btn primary" data-action="print-report">${icon("download")}${uiText("导出 PDF", "Export PDF")}</button>`)}<article class="report-page official-report" id="formalReport">${reportMarkup}</article></div>`;
    if (currentLanguage() === "en") window.AuditFlowI18n?.translateTree(document.getElementById("formalReport"));
    requestAnimationFrame(()=>refreshReportTocPageNumbers());
    setTimeout(refreshReportTocPageNumbers,350);
  }

  // v6.7: fills the Contents page column from the rendered A4-like report
  // sheets (each sheet is 1123px tall on screen, matching one print page).
  function refreshReportTocPageNumbers() {
    const report=document.getElementById("formalReport");
    if(!report)return;
    const sheets=report.querySelectorAll(".report-sheet[data-report-sheet]");
    const starts=new Map();let page=1;
    sheets.forEach(sheet=>{
      const label=sheet.getAttribute("data-report-sheet");
      if(label)starts.set(label,page);
      const height=sheet.getBoundingClientRect().height;
      page+=Math.max(1,Math.ceil((height-0.01)/1123));
    });
    report.querySelectorAll(".toc-page[data-toc-target]").forEach(cell=>{
      const label=cell.getAttribute("data-toc-target");
      cell.textContent=starts.get(label)||"—";
    });
  }

