      try { localStorage.setItem("auditflow-helix-panes-v1", JSON.stringify(ui.helixReviewPanes)); } catch {}
      const layout = el.closest(".helix-review-workbench")?.querySelector(".helix-review-shell");
      const panes = [
        { key: "tree", element: layout?.querySelector(".helix-review-tree") },
        { key: "list", element: layout?.querySelector(".helix-review-list") },
        { key: "editor", element: layout?.querySelector(".helix-review-editor-pane") }
      ];
      if (layout && panes.every(pane => pane.element)) {
        const visible = panes.filter(pane => !ui.helixReviewPanes[pane.key]);
        const total = visible.reduce((sum, pane) => sum + Math.max(12, Number(ui.helixReviewWidths[panes.indexOf(pane)]) || 20), 0) || 1;
        const tracks = [];
        let precedingPercent = 0;
        visible.forEach((pane, index) => {
          const weight = Math.max(12, Number(ui.helixReviewWidths[panes.indexOf(pane)]) || 20);
          pane.element.style.display = "";
          pane.element.style.gridColumn = String(index * 2 + 1);
          tracks.push(`minmax(0, ${weight}fr)`);
          if (index < visible.length - 1) tracks.push("8px");
          precedingPercent += weight / total * 100;
          const handle = layout.querySelector(`.af-splitter-${index === 0 ? "left" : "center"}`);
          if (handle) {
            handle.style.display = index < visible.length - 1 ? "" : "none";
            if (index < visible.length - 1) handle.style.left = `${precedingPercent}%`;
          }
        });
        panes.filter(pane => ui.helixReviewPanes[pane.key]).forEach(pane => { pane.element.style.display = "none"; pane.element.style.gridColumn = ""; });
        layout.querySelectorAll(".af-splitter").forEach((handle, index) => { if (index >= visible.length - 1) handle.style.display = "none"; });
        layout.style.gridTemplateColumns = tracks.length ? tracks.join(" ") : "1fr";
      }
      const collapsed = ui.helixReviewPanes[paneKey];
      const paneLabels = { tree: ["目录树", "item tree"], list: ["描述列表", "description list"], editor: ["详情", "item details"] };
      const [zh, english] = paneLabels[paneKey];
